  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '工单分类子类信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of category_subcat
-- ----------------------------

-- ----------------------------
-- Table structure for contract
-- ----------------------------
DROP TABLE IF EXISTS `contract`;
CREATE TABLE `contract`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT 0 COMMENT '机构ID',
  `park_id` bigint(20) NULL DEFAULT NULL COMMENT '园区id',
  `build_id` bigint(20) NULL DEFAULT 0 COMMENT '楼宇id(建筑id)',
  `owner_id` bigint(20) NULL DEFAULT 0 COMMENT '租客id',
  `industry` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '行业id',
  `status` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '合同状态0=新建待审核1=正常执行中2=变更待审核3=变更待修改4=退租待审批5=退租待执行6=已退租7=作废待审批8=作废待修改9=到期未处理10=已驳回11=已作废12=已撤回13=待执行14=续租待审批15=已到期',
  `legal_person` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '法人姓名',
  `signed_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '签订人姓名',
  `followup_uid` bigint(20) NOT NULL DEFAULT 0 COMMENT '跟进人uid',
  `template_id` bigint(20) NULL DEFAULT 0 COMMENT '合同模板id',
  `contract_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同编号',
  `operator_id` bigint(20) NULL DEFAULT NULL COMMENT '经办人id',
  `signing_date` datetime NULL DEFAULT NULL COMMENT '签订日期',
  `unit_price_point` int(11) NULL DEFAULT NULL COMMENT '单价保留小数点几位',
  `calculation_accuracy` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '计算精度0=精确计算结果保留两位1=每步计算保留两位',
  `calculation_order` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计算顺序0=单价*面积*时间1=单价*时间*面积',
  `is_receivable_integer` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应收整数是否四舍五入0=否1=是',
  `starting_late_fee_day` int(11) NULL DEFAULT NULL COMMENT '滞纳金起算天数',
  `late_fee_ratio` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '滞纳金比例%',
  `upper_limit_late_fee` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '滞纳金上限%',
  `build_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '楼宇名称',
  `room_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '房号id,多个用英文逗号拼接;例:101,103',
  `lease_square` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租赁数(单位㎡/个)',
  `contract_start_time` date NULL DEFAULT NULL COMMENT '合同开始时间',
  `contract_end_time` date NULL DEFAULT NULL COMMENT '合同结束时间',
  `lease_retreat_time` date NULL DEFAULT NULL COMMENT '退租时间',
  `followup_uname` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '跟进人名称',
  `lease_unit_price` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租赁条款单价',
  `property_unit_price` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物业条款单价',
  `lease_unit_realprice` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租赁条款实时单价;若存在实时变更,可关联查询楼宇实时单价',
  `property_unit_realprice` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物业条款实时单价;若存在实时变更,可关联查询楼宇实时单价',
  `lease_price` decimal(19, 2) NULL DEFAULT NULL COMMENT '总计租金;保留两位小数',
  `scene` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同类型/合同应用场景;普通租赁合同(normal)/退租合同(retreat)/物业合同(property)等等 多个用英文逗号连接',
  `clause` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '条款类型;普通租赁条款(normal)/退租条款(retreat)/物业条款(property)等等 多个用英文逗号连接',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户编号',
  `is_whether_lease` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否续租0=否1=是',
  `pdf_file_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '生成的pdf合同路径',
  `lease_area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租赁面积',
  `data_source` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同来源0=新建1=导入',
  `checked_build` json NULL COMMENT '已选中楼宇资源',
  `is_bill_overdue` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '账单明细是否存在预期0=否1=是',
  `renewal_contract_id` bigint(20) NULL DEFAULT NULL COMMENT '续租合同Id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`org_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 206 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构合同表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of contract
-- ----------------------------

-- ----------------------------
-- Table structure for contract_annex
-- ----------------------------
DROP TABLE IF EXISTS `contract_annex`;
CREATE TABLE `contract_annex`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `contract_id` int(11) NOT NULL DEFAULT 0 COMMENT '基础合同,合同主表id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件名/文件夹',
  `annex_source` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1=pc;2=phone',
  `file_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件路径',
  `creator` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` bigint(20) NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构合同附件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of contract_annex
-- ----------------------------

-- ----------------------------
-- Table structure for contract_expense_clause
-- ----------------------------
DROP TABLE IF EXISTS `contract_expense_clause`;
CREATE TABLE `contract_expense_clause`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` int(11) NOT NULL DEFAULT 0 COMMENT '机构ID',
  `contract_id` int(11) NOT NULL DEFAULT 0 COMMENT '基础合同,合同主表id',
  `clause_id` int(11) NULL DEFAULT NULL COMMENT '条款id',
  `clause_type` int(11) NULL DEFAULT 1 COMMENT '条款类型(属性);1=租赁条款;2=物业条款',
  `attribute` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '费用条款属性',
  `basic_clause` json NULL COMMENT '基本条款',
  `bond_clause` json NULL COMMENT '保证金条款',
  `tax_clause` json NULL COMMENT '税率规则条款',
  `multiple_clause` json NULL COMMENT '综合条款(租期条款/物业费条款/经营管理费/停车费/)',
  `increment_clause` json NULL COMMENT '递增条款',
  `discount_clause` json NULL COMMENT '优惠条款',
  `remark_clause` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '备注条款',
  `report_detail` json NULL COMMENT '租金明细报表json',
  `discount_price` decimal(19, 2) NULL DEFAULT 0.00 COMMENT '优惠金额',
  `discount_data` json NULL COMMENT '优惠信息',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`org_id`) USING BTREE,
  INDEX `idx_clause_id`(`clause_id`) USING BTREE,
  INDEX `idx_clause_type`(`clause_type`) USING BTREE,
  INDEX `idx_contract_id`(`contract_id`) USING BTREE,
  INDEX `idx_attribute`(`attribute`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 384 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构合同费用条款附加表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of contract_expense_clause
-- ----------------------------

-- ----------------------------
-- Table structure for contract_expire_rule
-- ----------------------------
DROP TABLE IF EXISTS `contract_expire_rule`;
CREATE TABLE `contract_expire_rule`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户id',
  `rule_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同到期规则名称',
  `relation_builds` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联楼宇id，多个id用逗号隔开',
  `reminder_method` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '提醒方式0=站内1=公众号【数据字典:REMINDER_METHOD】',
  `reminder_day` int(11) NULL DEFAULT NULL COMMENT '提前几天提醒(天)',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_rule_name`(`rule_name`) USING BTREE,
  INDEX `idx_org_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '合同到期提醒规则表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of contract_expire_rule
-- ----------------------------

-- ----------------------------
-- Table structure for contract_operate_log
-- ----------------------------
DROP TABLE IF EXISTS `contract_operate_log`;
CREATE TABLE `contract_operate_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `contract_id` int(11) NOT NULL DEFAULT 0 COMMENT '基础合同,合同主表id',
  `operate_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作类型',
  `operate_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '操作内容',
  `other_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '其他备注',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_contract_id`(`contract_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 94 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '合同操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of contract_operate_log
-- ----------------------------

-- ----------------------------
-- Table structure for contract_order_bill
-- ----------------------------
DROP TABLE IF EXISTS `contract_order_bill`;
CREATE TABLE `contract_order_bill`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `contract_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '合同id',
  `order_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '明细编号',
  `number` int(11) NULL DEFAULT 0 COMMENT '还款期数',
  `pay_start_date` date NOT NULL COMMENT '还款周期开始时间',
  `pay_end_date` date NOT NULL COMMENT '还款周期结束时间',
  `fee_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '费用类型0=保证金1=租金3=物业费保证金4=物业费',
  `pay_date` date NOT NULL COMMENT '付款日期',
  `final_unit_price` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0.00' COMMENT '最终单价(含税)',
  `receivable` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0.00' COMMENT '应收(含税)【不包含逾期金额】',
  `tax_rate` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0.00' COMMENT '税率',
  `tax_amount` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0.00' COMMENT '税额',
  `receivable_payment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0.00' COMMENT '实收金额',
  `bill_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '状态0=未支付1=已支付2=逾期',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户编号',
  `count` int(11) NULL DEFAULT 1 COMMENT '第几次账单',
  `bill_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '账单类型;1=收款(机构收款);2=付款(机构付款);',
  `late_fee` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '滞纳金(应收滞纳金)',
  `generate_late_fee` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '滞纳金(产生滞纳金【调整滞纳金，当前字段值不会改变】)',
  `overdue_day` int(11) NULL DEFAULT 0 COMMENT '逾期天数',
  `late_fee_pay_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '滞纳金付款状态0=未产生滞纳金1=未支付2=已结清',
  `data_source` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '账单来源0=系统生成1=手动添加',
  `starting_late_fee_day` int(11) NULL DEFAULT NULL COMMENT '滞纳金起算天数',
  `late_fee_ratio` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '滞纳金比例%',
  `upper_limit_late_fee` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '滞纳金上限%',
  `bill_source` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '账单来源;1=合同账单;2=物业管理账单;3=已关联合',
  `clause_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '账单条款类型1=租赁条款;2=物业条款',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '账单备注',
  `close_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '账单关闭状态;0=关闭;1=开启;',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 751 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构合同账单明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of contract_order_bill
-- ----------------------------

-- ----------------------------
-- Table structure for contract_selected_propertie
-- ----------------------------
DROP TABLE IF EXISTS `contract_selected_propertie`;
CREATE TABLE `contract_selected_propertie`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `contract_id` bigint(20) NOT NULL COMMENT '合同id',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户编号',
  `park_id` bigint(20) NOT NULL COMMENT '园区id',
  `build_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '楼宇id',
  `village_room_id` bigint(20) NOT NULL COMMENT '房间id',
  `rental_area` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '已选房源租赁面积',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '租赁状态0=已租赁1=退租',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`contract_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 268 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '合同中选中房源' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of contract_selected_propertie
-- ----------------------------

-- ----------------------------
-- Table structure for contract_template
-- ----------------------------
DROP TABLE IF EXISTS `contract_template`;
CREATE TABLE `contract_template`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT 0 COMMENT '机构ID',
  `watermark_id` bigint(20) NULL DEFAULT NULL COMMENT '水印模板id',
  `scene` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应用场景;普通合同(normal)/退租合同(retreat)等等',
  `template_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `template_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板文件',
  `basic_clause` json NULL COMMENT '模板主条款信息',
  `number_rule` json NULL COMMENT '模板合同编号规则',
  `latefee_clause` json NULL COMMENT '滞纳金条款',
  `multiple_clause` json NULL COMMENT '综合条款',
  `relation_builds` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '楼宇id,多个id使用逗号隔开',
  `table_fields` json NULL COMMENT '模板变量自定义表头集合',
  `date_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '永久标识;1=永久',
  `timeout_time` datetime NULL DEFAULT NULL COMMENT '过期时间',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '模板使用状态;1=启用;0=关闭',
  `creator` bigint(20) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` bigint(20) NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`org_id`) USING BTREE,
  INDEX `idx_watermark_id`(`watermark_id`) USING BTREE,
  INDEX `idx_scene`(`scene`) USING BTREE,
  INDEX `idx_template_name`(`template_name`) USING BTREE,
  INDEX `idx_date_flag`(`date_flag`) USING BTREE,
  INDEX `idx_timeout_time`(`timeout_time`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_oss_updated_at`(`org_id`, `scene`, `status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 686 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构合同模板配置表' ROW_FORMAT = Dynamic;

