-- ----------------------------
-- Table structure for energy
-- ----------------------------
DROP TABLE IF EXISTS `energy`;
CREATE TABLE `energy`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `type` bigint(20) NOT NULL DEFAULT 1 COMMENT '设备表种类',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `village_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '项目ID',
  `build_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '楼宇ID',
  `purpose` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '用途 1-分表 2-总表 3-公摊表',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表具编号',
  `magnification` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '倍率',
  `original_reading` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '原始读数',
  `max_reading` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '最大读数',
  `meter_time` date NULL DEFAULT NULL COMMENT '抄录时间',
  `public_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '公摊方式 1-不公摊 2-按分表用量比例公摊 3-按租客租赁面积比例公摊 4-按房源数量平均公摊',
  `builds` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '授予用户管理的项目和楼宇，json存储',
  `layer_ids` varchar(5000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '楼层id,1,2,3',
  `room_ids` varchar(5000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '绑定房间信息，1,2,3',
  `contract_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同ids',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '状态，1启动，0审核中，4禁用',
  `device_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '厂商id',
  `device_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备类型',
  `device_serial` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备序列号',
  `property_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '资产的ID',
  `device_off` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '设备通断状态 0通，1断',
  `device_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '设备状态 0无 1离线 2断电 3电量过低',
  `last_heart_time` datetime NULL DEFAULT NULL COMMENT '上次心跳时间',
  `remote_valve_control` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '是否开启远程阀控/1是0否',
  `is_remind` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '是否提醒过 1是0否、send_remind_value(低于提醒值)，send_zero_value（小于0）',
  `current_remaining` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '当前余量',
  `payment_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '付费类型 0是后付费 1是预付费',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '自定义表' ROW_FORMAT = Dynamic;

