-- ----------------------------
-- Table structure for energy_bill
-- ----------------------------
DROP TABLE IF EXISTS `energy_bill`;
CREATE TABLE `energy_bill`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '设备表种类',
  `bill_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '账单编号',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `village_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '项目ID',
