  `owner_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租客ID',
  `energy_record_ids` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '涉及抄表记录ids',
  `contract_id` bigint(20) NULL DEFAULT 0 COMMENT '合同信息',
  `start_time` date NULL DEFAULT NULL COMMENT '起始时间',
  `end_time` date NULL DEFAULT NULL COMMENT '结束时间',
  `part_use` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '分表用量',
  `part_amount` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '分表金额',
