  `receivable_payment_time` datetime NULL DEFAULT NULL COMMENT '账单应付时间',
  `total_amount` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '总计金额',
  `room_ids` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '房间ids',
  `is_new_owner` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '状态，1是，0否',
  `late_fee` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '滞纳金;{\"startDay\":10,\"ratio\":50,\"toplimit\":80}',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '2' COMMENT '状态，1已生成，2待生成，3禁用',
  `business_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '2' COMMENT '生成流水状态，1已产生，2未产成，3禁用',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL COMMENT '是否删除',
