-- ----------------------------
DROP TABLE IF EXISTS `energy_price`;
CREATE TABLE `energy_price`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '设备表种类',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
