  `effect_date` date NULL DEFAULT NULL COMMENT '生效时间',
  `is_stage_price` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否阶梯价 1是 0否',
  `tax_rate` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '倍率',
  `unit_price` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '单价标准，json存储',
  `builds` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '授予用户管理的项目和楼宇，json存储',
  `room_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '绑定房间信息，1,2,3',
  `ratio` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '滞纳金比例',
  `start_day` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '起算天数',
