  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '任务状态;1=待开始;2=抄表中;',
  `has_loop` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '周期状态',
  `third_task_id` bigint(20) NULL DEFAULT NULL COMMENT '第三方任务id',
  `is_stop` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '任务是否异常终止;',
  `stop_log` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '任务终止异常log',
