-- ----------------------------
-- Table structure for org
-- ----------------------------
DROP TABLE IF EXISTS `org`;
CREATE TABLE `org`  (
  `id` bigint(20) UNSIGNED NOT NULL COMMENT '编号',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '机构缩写名称',
  `admin_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '管理员用户id',
  `company` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '机构全名称',
  `province_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '省份id',
  `city_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '市id',
  `district_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '省市地址;英文逗号,拼接',
  `info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '机构介绍',
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '机构logo',
  `square_logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '正方形logo（建议透明的白色）',
  `total` int(11) NOT NULL DEFAULT 0 COMMENT '机构总人数',
  `tel` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系电话',
  `address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系地址',
  `type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '机构类别',
  `domain_prefix` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '机构专属域名前缀（若不填写则访问专属域名时展示平台信息，例如 admin-id.xxx.com）',
  `is_oem` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否为OEM',
  `wechat_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '公众号的微信号',
  `org_prefix` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '机构成员工号前缀(支持自定义)',
  `join_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '机构码(8位随机字符串)',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '机构状态，1启动，0审核中，4禁用',
  `dictionary` json NULL COMMENT '字典（替换页面上的字）',
  `module` json NULL COMMENT '支持开放的模块权限',
  `village_type` json NULL COMMENT '允许的项目类型',
  `overdue_day` datetime NULL DEFAULT NULL COMMENT '过期日期（当天23:59才过期）',
  `clue_tel` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '招商电话',
  `clue_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '招商时间',
  `reg_from` tinyint(4) NOT NULL DEFAULT 0 COMMENT '注册来源(0自己注册，1企微，2后台添加，3钉钉...)',
  `max_use_area` decimal(19, 2) NULL DEFAULT NULL COMMENT '最大可使用面积',
  `max_use_room` int(11) NULL DEFAULT NULL COMMENT '最大可使用房间数',
  `last_login_time` timestamp NULL DEFAULT NULL COMMENT '最后登录时间',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_join_code`(`join_code`) USING BTREE,
  INDEX `idx_type`(`type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of org
-- ----------------------------

-- ----------------------------
-- Table structure for org_account
-- ----------------------------
DROP TABLE IF EXISTS `org_account`;
CREATE TABLE `org_account`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '条目名称',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `company` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收款公司',
  `bank` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '银行账号',
  `subject` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '总分类账科目',
  `build` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应用的楼宇',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '是否启用0=否1=是',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`tenant_id`) USING BTREE,
  INDEX `idx_deleted_at`(`deleted`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '收支账户配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of org_account
-- ----------------------------

-- ----------------------------
-- Table structure for org_bill_annex
-- ----------------------------
DROP TABLE IF EXISTS `org_bill_annex`;
CREATE TABLE `org_bill_annex`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '机构ID',
  `object_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '附件唯一标识',
  `source_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '流水id',
  `parent_id` bigint(20) NULL DEFAULT NULL COMMENT '父级id',
  `sort` bigint(20) NOT NULL DEFAULT 1 COMMENT '置顶排序',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件名/文件夹',
  `type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '账单操作类型;1=账单附件;2=流水附件',
  `annex_source` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '1=pc;2=phone',
  `file_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件路径',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`tenant_id`) USING BTREE,
  INDEX `idx_object_id`(`object_id`) USING BTREE,
  INDEX `idx_parent_id`(`parent_id`) USING BTREE,
  INDEX `idx_sort`(`sort`) USING BTREE,
  INDEX `idx_source_id`(`source_id`) USING BTREE,
  INDEX `idx_type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构账单收支流水附件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of org_bill_annex
-- ----------------------------

-- ----------------------------
-- Table structure for org_bill_cost_category
-- ----------------------------
DROP TABLE IF EXISTS `org_bill_cost_category`;
CREATE TABLE `org_bill_cost_category`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '机构id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '费用分类名称',
  `is_bond` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否设置为保证金类型0=否1=是',
  `is_root` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否系统内置0=否1=是',
  `parent_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '父级id',
  `level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类层级',
  `sort` int(11) NULL DEFAULT 0 COMMENT '排序',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '创建人uid',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '修改人uid',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_cuser_uid`(`creator`) USING BTREE,
  INDEX `idx_muser_uid`(`updater`) USING BTREE,
  INDEX `idx_created_at`(`create_time`) USING BTREE,
  INDEX `idx_org_id`(`tenant_id`) USING BTREE,
  INDEX `idx_name`(`name`) USING BTREE,
  INDEX `idx_is_bond`(`is_bond`) USING BTREE,
  INDEX `idx_is_root`(`is_root`) USING BTREE,
  INDEX `idx_parent_id`(`parent_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 885 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '账单费用分类表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of org_bill_cost_category
-- ----------------------------

-- ----------------------------
-- Table structure for org_bill_cost_type
-- ----------------------------
DROP TABLE IF EXISTS `org_bill_cost_type`;
CREATE TABLE `org_bill_cost_type`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '机构id',
  `category_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '费用分类id',
  `is_bond` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否为保证金类型',
  `is_root` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否系统内置',
  `is_important` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '必须缴费的项目，否则影响业务使用0=否1=是',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '费用类型名称',
  `cost_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '费用类型',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '费用状态0=否1=是',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '创建人uid',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '修改人uid',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_cuser_uid`(`creator`) USING BTREE,
  INDEX `idx_muser_uid`(`updater`) USING BTREE,
  INDEX `idx_created_at`(`create_time`) USING BTREE,
  INDEX `idx_org_id`(`tenant_id`) USING BTREE,
  INDEX `idx_category_id`(`category_id`) USING BTREE,
  INDEX `idx_is_bond`(`is_bond`) USING BTREE,
  INDEX `idx_is_root`(`is_root`) USING BTREE,
  INDEX `idx_name`(`name`) USING BTREE,
  INDEX `idx_cost_type`(`cost_type`) USING BTREE,
  INDEX `idx_sort`(`sort`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `index_oci_name`(`tenant_id`, `category_id`, `is_root`, `name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8127 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '账单费用类型表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of org_bill_cost_type
-- ----------------------------

-- ----------------------------
-- Table structure for org_bill_invoice
-- ----------------------------
DROP TABLE IF EXISTS `org_bill_invoice`;
CREATE TABLE `org_bill_invoice`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `village_id` bigint(20) NULL DEFAULT NULL COMMENT '项目id',
  `build_id` bigint(20) NULL DEFAULT NULL COMMENT '楼宇id',
  `bill_id` bigint(20) NULL DEFAULT NULL COMMENT '账单id',
  `subbill_id` bigint(20) NULL DEFAULT NULL COMMENT '子账单ID',
  `build_bind` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '绑定楼宇信息json',
  `room_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '房号json',
  `seller_id` bigint(20) NULL DEFAULT NULL COMMENT '售方id',
  `owner_id` bigint(20) NULL DEFAULT NULL COMMENT '买方(租客)id',
  `buyer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '购方名称',
  `buyer_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '购方(租客)开户行账号',
  `goods_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '货物类型;1=停车费;2=租金;',
  `cost_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '账单费用类型',
  `invoice_time` datetime NULL DEFAULT NULL COMMENT '开票时间',
  `invoice_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '发票状态;1=待开票;2=已开票;3=已冲红;4=已作废;5=已开负数发票;6=作废审批中;',
  `invoice_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发票编号',
  `record_price` decimal(19, 2) NULL DEFAULT NULL COMMENT '开票记录金额',
  `invoice_price` decimal(19, 2) NULL DEFAULT NULL COMMENT '已开票金额',
  `can_invoice_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '可开票金额',
  `apply_invoice_amount` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '申请开票金额',
  `tax_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '税额',
  `tax_rate` int(11) NULL DEFAULT NULL COMMENT '税率',
  `unit_price` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '单价',
  `total` int(11) NULL DEFAULT NULL COMMENT '数量',
  `tax_cost_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '商品或服务名称',
  `specs` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规格',
  `invoice_unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单位',
  `buyer_bank` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '购方开户行',
  `invoice_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发票代码',
  `buyer_tax_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '购方税号',
  `buyer_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '购方电话',
  `buyer_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '购方地址',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '备注',
  `nopay_tax_price` decimal(19, 2) NULL DEFAULT NULL COMMENT '未交税金额',
  `tax_price_amount` decimal(19, 2) NULL DEFAULT NULL COMMENT '价税合计',
  `saler_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '售方名称',
  `saler_account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '售方开户行账号',
  `saler_bank` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '售方银行',
  `saler_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '售方地址',
  `saler_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '售方电话',
  `saler_tax_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '售方税号(纳税人识别号)',
  `extra_time` timestamp NULL DEFAULT NULL COMMENT '作废/红冲日期',
  `invoice_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开票类型;1=增值税普通发票;2=增值税专用发票;3=增值税电子普通发票;',
  `task_key` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开票批次凭证',
  `group_key` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分组批次凭证',
  `issue_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作开票类型;1=提前开票;2=实收开票',
  `red_invoice_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '冲红发票号码',
  `red_invoice_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '冲红发票代码',
  `red_invoice_time` datetime NULL DEFAULT NULL COMMENT '冲红发票开具时间',
  `can_e_invoice` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否需要开具电子发票 1需要 0不需要',
  `e_invoice_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '电子发票开具状态 0未开票 1开票成功 2开票中 3开票失败',
  `e_invoice_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '电子发票订单ID',
  `e_invoice_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '电子发票链接',
  `e_invoice_error` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开具电子发票失败原因',
  `red_e_invoice_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '冲红电子发票开具状态 0未开票 1开票成功 2开票中 3开票失败',
  `red_e_invoice_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '冲红电子发票订单ID',
  `red_e_invoice_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '冲红电子发票链接',
  `red_e_invoice_error` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '冲红电子发票失败原因',
  `service` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'org' COMMENT '服务名称',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作人uid',
  `create_time` datetime NULL DEFAULT NULL COMMENT '操作时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构账单开票记录表' ROW_FORMAT = Dynamic;

