-- ----------------------------
-- Table structure for org_bill_notice
-- ----------------------------
DROP TABLE IF EXISTS `org_bill_notice`;
CREATE TABLE `org_bill_notice`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `tenant_id` bigint(20) NOT NULL COMMENT '机构id',
  `owner_id` bigint(20) NULL DEFAULT NULL COMMENT '租客id',
  `contract_id` bigint(20) NULL DEFAULT NULL COMMENT '合同id',
  `contract_bill_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同账单明细id集合',
  `build_id` bigint(20) NULL DEFAULT NULL COMMENT '绑定的楼宇id',
  `build_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '生成方式;1=逐张生成;2=按租客合并;3=按合同合并;',
  `notice_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通知方式;1=下载打印;2=短信通知;3=邮件通知;4=站内信',
  `pack_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '2' COMMENT '打包方式;1=逐张打包;2=合并zip',
  `account_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收支账户id',
  `sms_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '短信发送状态;1=失败;2=成功',
  `email_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱发送状态;1=失败;2=成功',
  `wechat_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信发送状态;1=失败;2=成功',
  `mail_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '站内信发送状态1=失败2=成功',
  `has_qrcode` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '附收款二维码;1=是;0=否',
  `form_data` json NULL COMMENT '通知单原始json',
  `bill_data` json NULL COMMENT '通知单涉及源账单信息',
  `file_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通知单文件路径',
  `task_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '生成批次标识task_key',
  `build_date` date NULL DEFAULT NULL COMMENT '生成日期',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作人uid',
  `create_time` datetime NULL DEFAULT NULL COMMENT '操作时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 104 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '收款通知记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of org_bill_notice
