-- ----------------------------
-- Table structure for org_bill_receipt
-- ----------------------------
DROP TABLE IF EXISTS `org_bill_receipt`;
CREATE TABLE `org_bill_receipt`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `village_id` bigint(20) NULL DEFAULT NULL COMMENT '项目id',
  `build_id` bigint(20) NULL DEFAULT NULL COMMENT '楼宇id',
  `bill_id` bigint(20) NULL DEFAULT NULL COMMENT '账单id',
  `subbill_id` bigint(20) NULL DEFAULT NULL COMMENT '子账单ID',
  `rule_id` bigint(20) NULL DEFAULT NULL COMMENT '账单收据编号规则id',
  `room_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '房号',
  `payment_company_id` bigint(20) NULL DEFAULT NULL COMMENT '交款公司/单位id',
  `payment_company` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '交款单位',
  `payment_uname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '交款人',
  `payment_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '交款方地址',
  `payment_phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '交款方电话',
  `receipt_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收据编号',
  `receipt_int` int(11) NULL DEFAULT NULL COMMENT '编号数值',
  `number_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '生成编号方式;1=规则生成;2=自定义',
  `price` decimal(19, 2) NULL DEFAULT NULL COMMENT '收据金额',
  `can_receipt_amount` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '可开据金额',
  `apply_receipt_amount` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '申请开据金额',
  `currency` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '币种',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收据状态;1=已发出;2=已回收;3=新建待审批;4=作废待审批;5=已作废;6=未发出;',
  `payment_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '交款人uid',
  `collection_company_id` bigint(20) NULL DEFAULT NULL COMMENT '收款公司/单位id',
  `collection_company` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收款单位',
  `collection_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收款人uid',
  `collection_uname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收款方收款人',
  `collection_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收款方地址',
  `collection_phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收款方电话',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '备注',
  `remit_type` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '汇款方式',
  `cost_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '费用类型',
  `cost_name` varchar(155) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '费用名称',
  `task_key` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开据批次凭证',
  `group_key` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开据分组凭证',
  `issuer_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开据人',
  `issuer_time` datetime NULL DEFAULT NULL COMMENT '开据时间',
  `apply_template_id` bigint(20) NULL DEFAULT NULL COMMENT '收据当前应用模板id',
  `apply_template` json NULL COMMENT '收据当前应用模板生成数据',
  `receopt_file_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '生成收据url',
  `apply_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '发票生成状态;0=未生成 1=生成中 2=已生成',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`tenant_id`) USING BTREE,
  INDEX `idx_currency`(`currency`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_collection_company`(`collection_company`) USING BTREE,
  INDEX `idx_receipt_number`(`receipt_number`) USING BTREE,
  INDEX `idx_cost_type`(`cost_type`) USING BTREE,
  INDEX `idx_payment_uid`(`payment_uid`) USING BTREE,
  INDEX `idx_collection_uid`(`collection_uid`) USING BTREE,
  INDEX `idx_issuer_uid`(`issuer_uid`) USING BTREE,
  INDEX `idx_issuer_time`(`issuer_time`) USING BTREE,
  INDEX `idx_payment_company_id`(`payment_company_id`) USING BTREE,
  INDEX `payment_company`(`payment_company`) USING BTREE,
  INDEX `idx_collection_company_id`(`collection_company_id`) USING BTREE,
  INDEX `idx_bill_id`(`bill_id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_build_id`(`build_id`) USING BTREE,
  INDEX `idx_rule_id`(`rule_id`) USING BTREE,
  INDEX `idx_number_type`(`number_type`) USING BTREE,
  INDEX `idx_task_key`(`task_key`) USING BTREE,
  INDEX `idx_group_key`(`group_key`) USING BTREE,
  INDEX `index_template_id`(`apply_template_id`) USING BTREE,
  INDEX `idx_apply_status`(`apply_status`) USING BTREE,
  INDEX `idx_subbill_id`(`subbill_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构账单收据表' ROW_FORMAT = Dynamic;

