-- ----------------------------
-- Table structure for org_bill_stream_middle
-- ----------------------------
DROP TABLE IF EXISTS `org_bill_stream_middle`;
CREATE TABLE `org_bill_stream_middle`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '机构id',
  `bill_id` bigint(20) NULL DEFAULT NULL COMMENT '账单id',
  `bill_type` bigint(20) NULL DEFAULT 1 COMMENT '账单类型',
  `stream_id` bigint(20) NULL DEFAULT NULL COMMENT '流水id',
  `company_id` bigint(20) NULL DEFAULT NULL COMMENT '公司id',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '公司名称(收款/付款地方单位名称)',
  `cost_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '费用类型',
  `income_date` date NULL DEFAULT NULL COMMENT '入账日期',
  `amount` decimal(19, 2) NULL DEFAULT NULL COMMENT '发生额',
  `match_price` decimal(19, 2) NULL DEFAULT NULL COMMENT '已匹配金额',
  `nomatch_price` decimal(19, 2) NULL DEFAULT NULL COMMENT '未匹配金额',
  `match_date` date NULL DEFAULT NULL COMMENT '匹配日期',
  `cancel_match_date` date NULL DEFAULT NULL COMMENT '取消匹配日期',
  `match_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '匹配状态;1=完全匹配;2=未匹配;3=部分匹配;4=已取消',
  `is_confirm` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '是否确认;1=待确认;2=已确认;',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `confirm_uid` int(11) NULL DEFAULT 0 COMMENT '确认人员uid',
  `unconfirm_time` timestamp NULL DEFAULT NULL COMMENT '取消确认时间',
  `unconfirm_uid` int(11) NULL DEFAULT 0 COMMENT '取消确认人员uid',
  `operate` json NULL COMMENT '操作权限',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 88 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构流水账单中间表【匹配】' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of org_bill_stream_middle
-- ----------------------------

-- ----------------------------
-- Table structure for org_charge
-- ----------------------------
DROP TABLE IF EXISTS `org_charge`;
CREATE TABLE `org_charge`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `tenant_id` bigint(20) NOT NULL COMMENT '机构Id',
  `name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准名称',
  `mode` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '计费模式：1-单价，2-单价*计量单位',
  `unit_price` decimal(19, 2) NOT NULL COMMENT '收费金额、单价(根据 mode 来决定)',
  `valid_time` datetime NOT NULL COMMENT '标准生效时间',
  `expire_time` datetime NOT NULL COMMENT '标准失效时间',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '状态：0-已失效，1-生效中',
  `unit` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '计量单位',
  `after_days_start_bill` int(11) NOT NULL DEFAULT 0 COMMENT '违约金起算天数',
  `every_day_pre` int(11) NOT NULL DEFAULT 0 COMMENT '违约金收取比例（天/%）',
  `upper_limit_fee` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '违约金上限(元)',
  `bind_object` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '绑定对象： 1-房间，2-车位',
  `village_id` bigint(20) NOT NULL COMMENT '园区Id',
  `bill_cost_type_id` bigint(20) NOT NULL COMMENT '账单费用类型表id',
  `unit_charging` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计费单位',
  `daily_unit_price_and_month_rule` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计费规则(天单价换算、月划分)',
  `pay_date_action` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '账单(应)付款时间-动作',
  `pay_date_days` int(11) NOT NULL COMMENT '天数（日）',
  `pay_date_action_type` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '账单(应)付款时间-方式',
  `pay_cycle` int(11) NOT NULL DEFAULT 1 COMMENT '付款周期（N月一付）',
  `divide_method` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '划分方式',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '操作人uid',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '修改人uid',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `charge_org_id_index`(`tenant_id`) USING BTREE,
  INDEX `charge_name_index`(`name`) USING BTREE,
  INDEX `charge_mode_index`(`mode`) USING BTREE,
  INDEX `charge_status_index`(`status`) USING BTREE,
  INDEX `charge_village_id_index`(`village_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '收费标准' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of org_charge
-- ----------------------------

-- ----------------------------
-- Table structure for org_contract_retreat
-- ----------------------------
DROP TABLE IF EXISTS `org_contract_retreat`;
CREATE TABLE `org_contract_retreat`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `owner_id` bigint(20) NULL DEFAULT NULL COMMENT '租客id',
  `contract_id` bigint(20) NULL DEFAULT NULL COMMENT '合同id',
  `apply_template_id` bigint(20) NULL DEFAULT NULL COMMENT '所应用的退租合同模板id',
  `build_bind` json NULL COMMENT '房源信息',
  `bill_info` json NULL COMMENT '历史账单信息',
  `bond_info` json NULL COMMENT '保证金',
  `total_cost` json NULL COMMENT '费用总计',
  `retreat_type` tinyint(4) NULL DEFAULT NULL COMMENT '退租类型',
  `retreat_reason` json NULL COMMENT '退租原因',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '备注信息',
  `apply_contract` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '根据所选模板生成的退租合同',
  `retreat_date` date NULL DEFAULT NULL COMMENT '退租日期',
  `bcc_change_date` date NULL DEFAULT NULL COMMENT '工商注册地址变更日期',
  `apply_retreat_date` datetime NULL DEFAULT NULL COMMENT '协议签订日期(申请退租日期)',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建日期',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改日期',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`tenant_id`) USING BTREE,
  INDEX `idx_apply_template_id`(`apply_template_id`) USING BTREE,
  INDEX `idx_contract_id`(`contract_id`) USING BTREE,
  INDEX `idx_cuser_uid`(`creator`) USING BTREE,
  INDEX `idx_created_at`(`updater`) USING BTREE,
  INDEX `idx_owner_id`(`owner_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 201 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构合同退租表' ROW_FORMAT = Dynamic;

