-- ----------------------------
-- Table structure for org_income
-- ----------------------------
DROP TABLE IF EXISTS `org_income`;
CREATE TABLE `org_income`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '机构id',
  `village_id` bigint(20) NULL DEFAULT NULL COMMENT '项目id',
  `contract_id` bigint(20) NULL DEFAULT NULL COMMENT '合同id',
  `bill_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '账单id',
  `bill_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '账单类型;1=收款;2=付款;',
  `stream_middle_id` bigint(20) NULL DEFAULT NULL COMMENT '子流水id',
  `contract_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同编号',
  `build_id` bigint(20) NULL DEFAULT NULL COMMENT '楼宇id',
  `industry_id` bigint(20) NULL DEFAULT NULL COMMENT '租客所属行业ID',
  `room_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '楼层-房间号;{\"room\": [{\"id\":\"1001\",\"room_id\":\"\",\"room_name\":\"\",\"layer_id\":\"\",\"unit_id\":\"\",\"zone_id\":\"\"}]}',
  `owner_id` bigint(20) NULL DEFAULT NULL COMMENT '租客id',
  `income_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '收入类型;1=应收(含税);2=应收(不含税);3=实收(含税);4=实收(不含税);',
  `is_confirm` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '是否确认;1=当月待确认;1=当月已确认;',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `confirm_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '确认人员uid',
  `unconfirm_time` datetime NULL DEFAULT NULL COMMENT '取消确认时间',
  `unconfirm_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '取消确认人员uid',
  `contract_cost_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '合同费用类型',
  `owner_cost_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租客费用类型',
  `cost_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '账单费用类型',
  `trade_amount` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '交易金额',
  `amount` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '含/不含税金额',
  `tax_amount` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '税额',
  `trade_time` datetime NULL DEFAULT NULL COMMENT '交易时间',
  `is_unreal_room` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '房屋虚拟标识.0=真实房屋;1=非真实房屋',
  `unreal_room` json NULL COMMENT '虚拟房屋信息',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '操作人uid',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '修改人uid',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`tenant_id`) USING BTREE,
  INDEX `idx_contract_id`(`contract_id`) USING BTREE,
  INDEX `idx_owner_id`(`owner_id`) USING BTREE,
  INDEX `idx_industry_id`(`industry_id`) USING BTREE,
  INDEX `idx_is_confirm`(`is_confirm`) USING BTREE,
  INDEX `idx_owner_cost_type`(`owner_cost_type`) USING BTREE,
  INDEX `idx_trade_time`(`trade_time`) USING BTREE,
  INDEX `idx_income_type`(`income_type`) USING BTREE,
  INDEX `idx_cost_type`(`cost_type`) USING BTREE,
  INDEX `idx_trade_amount`(`trade_amount`) USING BTREE,
  INDEX `idx_contract_cost_type`(`contract_cost_type`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_stream_middle_id`(`stream_middle_id`) USING BTREE,
  INDEX `idx_bill_id`(`bill_id`) USING BTREE,
  INDEX `idx_bill_type`(`bill_type`) USING BTREE,
  INDEX `idx_confirm_time`(`confirm_time`) USING BTREE,
  INDEX `idx_unconfirm_time`(`unconfirm_time`) USING BTREE,
  INDEX `idx_confirm_uid`(`confirm_uid`) USING BTREE,
  INDEX `idx_unconfirm_uid`(`unconfirm_uid`) USING BTREE,
  INDEX `idx_is_unreal_room`(`is_unreal_room`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2615 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构收入表' ROW_FORMAT = Dynamic;

