DROP TABLE IF EXISTS `org_remark`;
CREATE TABLE `org_remark`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `business_id` bigint(20) NULL DEFAULT NULL COMMENT '业务id;合同id/账单id/等等',
