-- ----------------------------
-- Table structure for owner
-- ----------------------------
DROP TABLE IF EXISTS `owner`;
CREATE TABLE `owner`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` int(11) NULL DEFAULT NULL COMMENT '机构ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租客名称',
  `is_personal` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否个人，1个人，0公司',
  `is_suggest` smallint(6) NOT NULL DEFAULT 0 COMMENT '是否推荐;0=不推荐;1=推荐;',
  `type` smallint(6) NOT NULL DEFAULT 0 COMMENT '目标对象;0=正常租客;1=收款对象;2=付款对象;',
  `sham` smallint(6) NOT NULL DEFAULT 0 COMMENT '虚拟身份注册;0=无;1=虚拟个人注册;2=虚拟企业注册;',
  `contact_id` int(11) NULL DEFAULT NULL COMMENT '联系人',
  `contact_sign_id` int(11) NULL DEFAULT NULL COMMENT '租客合同签署人id',
  `contact_notice_id` int(11) NULL DEFAULT NULL COMMENT '缴费通知单联系人',
  `approval_contact_id` int(11) NULL DEFAULT 0 COMMENT '审批联系人id',
  `certificate_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证件号码',
  `industry_id` int(11) NULL DEFAULT NULL COMMENT '行业分类id',
  `village_id_list` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租客绑定的项目id,使用，隔开',
  `build_bind` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '租客绑定的项目楼宇房源信息',
  `tel` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系方式',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱',
  `tenant_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '租客编码',
  `website_link` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '官网地址',
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '企业logo',
  `company_desc` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '企业简介',
  `business_info_founding_time` date NULL DEFAULT NULL COMMENT '成立日期',
  `business_info_business_term` date NULL DEFAULT NULL COMMENT '营业期限',
  `registered_capital` decimal(28, 2) NULL DEFAULT NULL COMMENT '注册资金',
  `invoice_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '开票信息',
  `business_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '工商信息',
  `tag_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '租客标签',
  `diy_field` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '自定义字段',
  `is_advance_notice` smallint(6) NULL DEFAULT 0 COMMENT '是否开启公司代付通知',
  `is_archive` smallint(6) NULL DEFAULT 0 COMMENT '是否归档',
  `bank` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开户行',
  `account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '账号',
  `bank_phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '电话',
  `taxpayer_identification_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '纳税人识别号',
  `invoice_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发票类型0=增值税普通发票1=增值税专用发票2=增值税电子普通发票',
  `billing_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开票地址',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`org_id`) USING BTREE,
  INDEX `idx_contact_id`(`contact_id`) USING BTREE,
  INDEX `idx_industry_id`(`industry_id`) USING BTREE,
  INDEX `idx_business_info_founding_time`(`business_info_founding_time`) USING BTREE,
  INDEX `idx_business_info_business_term`(`business_info_business_term`) USING BTREE,
  INDEX `idx_contact_notice_id`(`contact_notice_id`) USING BTREE,
  INDEX `idx_contact_sign_id`(`contact_sign_id`) USING BTREE,
  INDEX `idx_village_id`(`village_id_list`) USING BTREE,
  INDEX `idx_advance_notice`(`is_advance_notice`) USING BTREE,
  INDEX `idx_is_suggest`(`is_suggest`) USING BTREE,
  INDEX `idx_is_archive`(`is_archive`) USING BTREE,
  INDEX `idx_approval_contact_id`(`approval_contact_id`) USING BTREE,
  INDEX `idx_type`(`type`) USING BTREE,
  INDEX `idx_sham`(`sham`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '租客信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of owner
-- ----------------------------

-- ----------------------------
-- Table structure for owner_contacts
-- ----------------------------
DROP TABLE IF EXISTS `owner_contacts`;
CREATE TABLE `owner_contacts`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` int(11) NULL DEFAULT NULL COMMENT '机构ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系人姓名',
  `phone` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '手机',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱',
  `owner_id` int(11) NULL DEFAULT NULL COMMENT '所属公司id',
  `address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通讯地址',
  `is_default` tinyint(4) NOT NULL DEFAULT 1 COMMENT '是否默认联系人',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`org_id`) USING BTREE,
  INDEX `idx_owner_id`(`owner_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '租客联系人' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of owner_contacts
-- ----------------------------

-- ----------------------------
-- Table structure for owner_files
-- ----------------------------
DROP TABLE IF EXISTS `owner_files`;
CREATE TABLE `owner_files`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `owner_id` int(11) NOT NULL COMMENT '租客ID',
  `org_id` int(11) NOT NULL COMMENT '机构ID',
  `uid` int(11) NOT NULL COMMENT '用户服务ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件名',
  `url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件网址',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '租客附件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of owner_files
-- ----------------------------

-- ----------------------------
-- Table structure for owner_pay_set
-- ----------------------------
DROP TABLE IF EXISTS `owner_pay_set`;
CREATE TABLE `owner_pay_set`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` int(11) NULL DEFAULT NULL COMMENT '机构id',
  `village_id` int(11) NULL DEFAULT NULL COMMENT '所属项目id',
  `build_id` int(11) NULL DEFAULT NULL COMMENT '楼宇id',
  `owner_id` int(11) NULL DEFAULT NULL COMMENT '租客id',
  `cost_types` json NULL COMMENT '自动缴费费用类型设置',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`org_id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_build_id`(`build_id`) USING BTREE,
  INDEX `idx_owner_id`(`owner_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '企业自动缴费费用配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of owner_pay_set
-- ----------------------------

-- ----------------------------
-- Table structure for owner_remarks
-- ----------------------------
DROP TABLE IF EXISTS `owner_remarks`;
CREATE TABLE `owner_remarks`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `own_id` int(11) NOT NULL COMMENT '租客id',
  `org_id` int(11) NOT NULL COMMENT '机构id',
  `remark` varchar(5000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注内容',
  `operation_uid` int(11) NULL DEFAULT NULL COMMENT '操作人uid',
  `operation_name` int(11) NULL DEFAULT NULL COMMENT '操作人姓名',
  `operation_time` timestamp NULL DEFAULT NULL COMMENT '操作时间',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '租客备注信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of owner_remarks
-- ----------------------------

-- ----------------------------
-- Table structure for park
-- ----------------------------
DROP TABLE IF EXISTS `park`;
CREATE TABLE `park`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `park_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '停车场名称',
  `village_id` bigint(20) NOT NULL COMMENT '项目ID',
  `parent_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '上级停车场ID',
  `park_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '车场类型 0-默认 1-大华8900',
  `park_ip_port` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'ip端口',
  `level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '停车场级别字符串，逗号拼接上级id（便于场中场中场，例如地下经过地上，地下某区域被承包）',
  `temp_car` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '临时车政策（0允许进入，1登记/预约进入，2禁止进入）',
  `free_car` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '免费车类型（数字数组）',
  `bind_car_number` int(11) NOT NULL DEFAULT 3 COMMENT '限制车主自主绑定车辆数量',
  `must_bind_company` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '车主必须要绑定租客（0不绑定，1必须绑定）',
  `mobile_pay_month_fee` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '车主月租缴费（0不开启，1必须开启）',
  `mobile_pay_store_fee` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '车主余额储值（0不开启，1必须开启）',
  `presence_car_total` int(11) NOT NULL DEFAULT 0 COMMENT '在场车辆总数',
  `park_space_total` int(11) NOT NULL DEFAULT 0 COMMENT '停车位总数',
  `out_rule` json NULL COMMENT '出口车辆匹配规则',
  `lng` decimal(10, 6) NULL DEFAULT NULL COMMENT '落座经度（gcj02）',
  `lat` decimal(10, 6) NULL DEFAULT NULL COMMENT '落座纬度（gcj02）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '状态（1正常，0关闭）',
  `free_car_apply` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否开启免费车申请1是0否',
  `un_car_number_open` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '无牌车是否开闸0不开闸，1开闸',
  `extra` json NULL COMMENT '额外信息',
  `load_prop` int(11) NOT NULL DEFAULT 0 COMMENT '负载占比',
  `invoice` json NULL COMMENT '开发票配置',
  `more_car` int(11) NOT NULL DEFAULT 0 COMMENT '一个车位多辆车配置,0临时收费1禁止驶入',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_parent_id`(`parent_id`) USING BTREE,
  INDEX `idx_lng`(`lng`) USING BTREE,
  INDEX `idx_lat`(`lat`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '停车场（一个项目可以有多个场）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of park
-- ----------------------------

-- ----------------------------
-- Table structure for park_car_order
-- ----------------------------
DROP TABLE IF EXISTS `park_car_order`;
CREATE TABLE `park_car_order`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `order_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '订单号',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `village_id` bigint(20) NOT NULL COMMENT '项目ID',
  `park_id` bigint(20) NOT NULL COMMENT '停车场ID',
  `uid` bigint(20) NOT NULL COMMENT '用户服务的ID',
  `user_openid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '用户支付时的openid',
  `car_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '车牌号',
  `order_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '3' COMMENT '订单类别（1月租车，2储值车，3临时车）',
  `log_id` bigint(20) NULL DEFAULT NULL COMMENT '出入记录ID',
  `enter_time` datetime NULL DEFAULT NULL COMMENT '入场时间',
  `out_time` datetime NULL DEFAULT NULL COMMENT '离场时间',
  `order_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '订单名称',
  `order_info` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '订单详情数据',
  `order_money` decimal(11, 2) NULL DEFAULT NULL COMMENT '订单金额',
  `order_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '订单状态（0未支付，1已支付，2退款中，3已退款，4订单取消）',
  `is_direct` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否直付码（0预付码，1直付码）',
  `parent_gate_id` bigint(20) NULL DEFAULT 0 COMMENT '父级车道ID',
  `gate_id` bigint(20) NULL DEFAULT 0 COMMENT '直付码的出场出入口',
  `pay_money` decimal(11, 2) NULL DEFAULT NULL COMMENT '订单实付金额',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '订单支付时间',
  `cash_uid` bigint(20) NOT NULL DEFAULT 0 COMMENT '收款用户ID',
  `pay_order_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '支付服务的订单号，用于退款、查询',
  `pay_method` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '支付方式',
  `pay_method_txt` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '支付方式文本',
  `third_order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '第三方订单号',
  `charge_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '收费标准ID',
  `invoice_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '发票状态0未开具1已开具2开具中3开票失败',
  `invoice_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发票链接',
  `invoice_error` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '开票失败原因',
  `refund_money` decimal(11, 2) NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `refund_time` datetime NULL DEFAULT NULL COMMENT '退款时间',
  `coupon_id` bigint(20) NULL DEFAULT 0 COMMENT '优惠券id',
  `coupon_amount` decimal(8, 2) NULL DEFAULT 0.00 COMMENT '优惠券金额',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '退款理由',
  `pre_money` decimal(11, 2) UNSIGNED NULL DEFAULT NULL COMMENT '预计支付金额',
  `under_charge` decimal(8, 2) NULL DEFAULT 0.00 COMMENT '充电抵扣金额',
  `free_reason_id` bigint(20) NULL DEFAULT 0 COMMENT '免费出场原因id',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`org_id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_park_id`(`park_id`) USING BTREE,
  INDEX `idx_uid`(`uid`) USING BTREE,
  INDEX `idx_car_number`(`car_number`) USING BTREE,
  INDEX `idx_pay_method`(`pay_method`) USING BTREE,
  INDEX `idx_pay_time`(`pay_time`) USING BTREE,
  INDEX `idx_cash_uid`(`cash_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '车的收费订单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of park_car_order
-- ----------------------------

-- ----------------------------
-- Table structure for park_cars
-- ----------------------------
DROP TABLE IF EXISTS `park_cars`;
CREATE TABLE `park_cars`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `village_id` bigint(20) NOT NULL COMMENT '项目ID',
  `park_id` bigint(20) NOT NULL COMMENT '停车场ID',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '住户ID',
  `user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '用户姓名',
  `user_phone` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '用户手机号(128加密)',
  `car_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '车牌号',
  `car_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '车的类型（1蓝牌、黄牌等）',
  `charge_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管理类型（1月租车，2储值车，3登记/预约临时车）',
  `balance` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '余额（单位元）',
  `car_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '车的备注',
  `park_space` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '绑定的车位ID（允许多车多位所以用json）',
  `car_data` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '车的数据字段（例如发动机编号、车品牌等）',
  `add_from` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '数据录入来源（1后台，0租客）',
  `enable` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '当前名单是否有效（0：无效，1：有效）',
  `need_alarm` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '当前名单是否为黑名单（0：否，1：黑名单）',
  `enable_time` date NULL DEFAULT NULL COMMENT '生效时间',
  `overdue_time` date NULL DEFAULT NULL COMMENT '过期时间',
  `is_push` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否已经推送给停车主机（0没有，1推送成功，2推送失败），修改后重置成0',
  `push_result` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '推送主机的结果（主要展示失败原因）',
  `fee_charge_id` bigint(20) NULL DEFAULT NULL COMMENT '收费规则id',
  `space_num` int(11) NULL DEFAULT 1 COMMENT '车位数',
  `parent_id` bigint(20) NULL DEFAULT NULL COMMENT '主车辆id',
  `sub_car_num` int(11) NULL DEFAULT 0 COMMENT '子车辆数量',
  `vehicle_brand` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '车辆品牌',
  `vehicle_equipment_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '车辆设备号',
  `driving_license_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '行驶证号',
  `vehicle_color` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '车辆颜色',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_park_id`(`park_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_user_name`(`user_name`) USING BTREE,
  INDEX `idx_user_phone`(`user_phone`) USING BTREE,
  INDEX `idx_car_number`(`car_number`) USING BTREE,
  INDEX `idx_balance`(`balance`) USING BTREE,
  INDEX `idx_enable_time`(`enable_time`) USING BTREE,
  INDEX `idx_overdue_time`(`overdue_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '月租车白名单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of park_cars
-- ----------------------------

-- ----------------------------
-- Table structure for park_cars_operator_log
-- ----------------------------
DROP TABLE IF EXISTS `park_cars_operator_log`;
CREATE TABLE `park_cars_operator_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '0添加、1修改、2删除、3缴费，关联订单、4导入',
  `cars_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '车辆id',
  `order_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '订单id',
  `before` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '修改前',
  `after` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '修改后',
  `creator` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_cars_id`(`cars_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 49 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '车辆操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of park_cars_operator_log
-- ----------------------------

-- ----------------------------
-- Table structure for park_charge
-- ----------------------------
DROP TABLE IF EXISTS `park_charge`;
CREATE TABLE `park_charge`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `charge_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收费标准名称',
  `park_id` bigint(20) NOT NULL COMMENT '停车场ID',
  `village_id` bigint(20) NOT NULL COMMENT '项目ID',
  `car_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '适用车的类型（1蓝牌、黄牌等，参照D1）',
  `month_fee` decimal(8, 2) NULL DEFAULT NULL COMMENT '月租费用（null不支持缴费）',
  `month_overdue_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '月租车到期后类型（0临时车（可能不允许进入），1储值车）',
  `month_recharge_input` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '月租车自主缴费能输入月数（0不允许，1允许）',
  `month_recharge_package` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '月租车自主缴费套餐',
  `effective_date` date NOT NULL COMMENT '生效日期',
  `free_minute` int(11) NOT NULL DEFAULT 0 COMMENT '临时车免费时长（分钟）',
  `free_out_minute` int(11) NOT NULL DEFAULT 0 COMMENT '临时车免费出场时长（分钟）',
  `charge_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '临时车0标准收费，1按次收费，2按白天夜间收费，3按设定时间收费',
  `day_max_fee` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '临时车每日最高费用（0）不限',
  `charge_detail` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '临时车收费细则',
  `is_default` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否默认,1是0否',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_park_id`(`park_id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_effective_date`(`effective_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '停车场收费标准' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of park_charge
-- ----------------------------

