-- Records of patrol_location
-- ----------------------------

-- ----------------------------
-- Table structure for patrol_plan_equipment
-- ----------------------------
DROP TABLE IF EXISTS `patrol_plan_equipment`;
CREATE TABLE `patrol_plan_equipment`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT 0 COMMENT '机构ID',
  `application` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应用标识EQUIPMENT_INSPECTION=巡检;SECURITY_INSPECTION=安防',
  `plan_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计划编号',
  `plan_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计划名称',
  `station_id` bigint(20) NULL DEFAULT NULL COMMENT '责任岗位id',
  `department_id` bigint(20) NULL DEFAULT NULL COMMENT '责任部门id',
  `department_parent_id` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '责任部门父级id集合(多个使用逗号隔开)',
  `station_parent_id` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '责任岗位父级id集合(多个使用逗号隔开)',
  `start_date` datetime NULL DEFAULT NULL COMMENT '开始日期',
  `end_date` datetime NULL DEFAULT NULL COMMENT '截止日期',
  `date_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '日期永久标识',
  `time_out_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '超时处理规则类型;1=不处理;2=自动完成;3=挂起',
  `time_limit` int(11) NOT NULL DEFAULT 0 COMMENT '任务时限/小时',
  `work_order_app` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上报工单所属应用标识',
  `plan_rule` json NULL COMMENT '计划周期规则',
  `last_time` datetime NULL DEFAULT NULL COMMENT '最近一次执行时间',
  `next_time` datetime NULL DEFAULT NULL COMMENT '下次执行时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '计划执行结束时间',
  `patrol_order` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '巡检顺序;1=必须一次;2=可以随机',
  `remind_json` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '提醒方式及提醒规则',
  `plan_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '巡检计划状态',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '计划启用状态;0=关闭;1=开启',
  `in_advance` int(11) NOT NULL DEFAULT 0 COMMENT '提前完成的时间数量',
  `minute_time` int(11) NOT NULL DEFAULT 1 COMMENT '提前完成的时间单位，1是小时2是天3是分钟',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`org_id`) USING BTREE,
  INDEX `idx_application`(`application`) USING BTREE,
  INDEX `idx_plan_number`(`plan_number`) USING BTREE,
  INDEX `idx_start_date`(`start_date`) USING BTREE,
  INDEX `idx_end_date`(`end_date`) USING BTREE,
  INDEX `idx_date_flag`(`date_flag`) USING BTREE,
  INDEX `idx_timeout_type`(`time_out_type`) USING BTREE,
  INDEX `idx_workorder_app`(`work_order_app`) USING BTREE,
  INDEX `idx_last_time`(`last_time`) USING BTREE,
  INDEX `idx_next_time`(`next_time`) USING BTREE,
  INDEX `idx_end_time`(`end_time`) USING BTREE,
  INDEX `idx_plan_status`(`plan_status`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 44 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '巡检、安防应用计划表' ROW_FORMAT = Dynamic;

