  INDEX `idx_application`(`plan_id`) USING BTREE,
  INDEX `idx_plan_number`(`position_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 111 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '巡检、安防应用计划绑定巡检点表' ROW_FORMAT = Dynamic;

