-- ----------------------------
-- Table structure for patrol_record_equipment
-- ----------------------------
DROP TABLE IF EXISTS `patrol_record_equipment`;
CREATE TABLE `patrol_record_equipment`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `application` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '应用标识EQUIPMENT_INSPECTION=巡检;SECURITY_INSPECTION=安防',
  `plan_id` bigint(20) NULL DEFAULT NULL COMMENT '巡检计划id',
  `task_id` bigint(20) NULL DEFAULT NULL COMMENT '巡检任务id',
  `is_signed` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '是否应用签到',
  `sign_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '签到状态',
  `is_nfc` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '是否应用nfc签到',
  `patrol_position_id` bigint(20) NULL DEFAULT NULL COMMENT '巡检点id',
  `address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '巡检点位置信息',
  `uid` bigint(20) NULL DEFAULT NULL COMMENT '巡检人uid',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '巡检人名称',
  `position` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '巡检点名称',
  `launch_uid` bigint(20) NULL DEFAULT NULL COMMENT '工单发起人uid',
  `launch_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工单发起人名称',
  `time` datetime NULL DEFAULT NULL COMMENT '巡检时间',
  `form_id` bigint(20) NULL DEFAULT NULL COMMENT '所属表单id',
  `sort` int(11) NULL DEFAULT NULL COMMENT '序号',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '巡检内容信息',
  `workorder_app` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '巡检所选工单应用',
  `workorder_id` bigint(20) NULL DEFAULT NULL COMMENT '工单id',
  `workorder_number` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工单编号',
  `property_list` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '绑定的资产json',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '巡检状态;1=待开始2=正常3=异常未整改4=异常已整改5=跳过【字典值PATROL_RECORD_EQUIPMENT_STATUS】',
  `handle_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '整改处理状态;1=待处理;2=处理中;3=已处理',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 740 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '巡检、安防应用记录表' ROW_FORMAT = Dynamic;

