-- ----------------------------
-- Table structure for patrol_task_equipment
-- ----------------------------
DROP TABLE IF EXISTS `patrol_task_equipment`;
CREATE TABLE `patrol_task_equipment`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT 0 COMMENT '机构ID',
  `application` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '应用标识EQUIPMENT_INSPECTION=巡检;SECURITY_INSPECTION=安防',
  `plan_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '计划id',
  `patrol_order` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '巡检顺序;1=必须依次;2=可以随机',
  `task_cycle` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '任务周期',
  `task_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '任务key',
  `task_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '任务名称',
  `task_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '任务编号',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `should_time` datetime NULL DEFAULT NULL COMMENT '应开始时间',
  `remind_time` datetime NULL DEFAULT NULL COMMENT '任务提醒时间',
  `station_id` bigint(20) NULL DEFAULT NULL COMMENT '负责岗位id',
  `station_parent_id` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '责任岗位父级id集合(多个使用逗号隔开)',
  `department_id` bigint(20) NULL DEFAULT NULL COMMENT '责任部门id',
  `department_parent_id` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '责任部门父级id集合(多个使用逗号隔开)',
  `post_uids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '岗位部门人员uids',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `timeout_time` datetime NULL DEFAULT NULL COMMENT '超时时间',
  `is_timeout` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否超时',
  `is_remind` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否发送提醒',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '任务状态;1=待开始;2=巡检中;',
  `has_loop` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '周期状态',
  `third_task_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '第三方任务id',
  `is_stop` int(11) NOT NULL DEFAULT 0 COMMENT '任务是否异常终止;',
  `stop_log` json NULL COMMENT '任务终止异常log',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`org_id`) USING BTREE,
  INDEX `idx_application`(`application`) USING BTREE,
  INDEX `idx_plan_id`(`plan_id`) USING BTREE,
  INDEX `idx_patrol_order`(`patrol_order`) USING BTREE,
  INDEX `idx_task_key`(`task_key`) USING BTREE,
  INDEX `idx_task_name`(`task_name`) USING BTREE,
  INDEX `idx_task_number`(`task_number`) USING BTREE,
  INDEX `idx_start_time`(`start_time`) USING BTREE,
  INDEX `idx_should_time`(`should_time`) USING BTREE,
  INDEX `idx_remind_time`(`remind_time`) USING BTREE,
  INDEX `idx_end_time`(`end_time`) USING BTREE,
  INDEX `idx_timeout_time`(`timeout_time`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_is_timeout`(`is_timeout`) USING BTREE,
  INDEX `idx_is_remind`(`is_remind`) USING BTREE,
  INDEX `idx_has_loop`(`has_loop`) USING BTREE,
  INDEX `idx_third_task_id`(`third_task_id`) USING BTREE,
  INDEX `idx_is_stop`(`is_stop`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 551 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '巡检、安防应用任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of patrol_task_equipment
-- ----------------------------

