  `plan_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '计划id',
  `plan_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计划key',
