-- ----------------------------
-- Table structure for product_comment
-- ----------------------------
DROP TABLE IF EXISTS `product_comment`;
CREATE TABLE `product_comment`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '璇勮?缂栧彿锛屼富閿?嚜澧',
  `user_id` bigint(20) NOT NULL COMMENT '璇勪环浜虹殑鐢ㄦ埛缂栧彿锛屽叧鑱?MemberUserDO 鐨?id 缂栧彿',
  `user_nickname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '璇勪环浜哄悕绉',
  `user_avatar` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '璇勪环浜哄ご鍍',
  `anonymous` bit(1) NOT NULL COMMENT '鏄?惁鍖垮悕',
  `order_id` bigint(20) NULL DEFAULT 0 COMMENT '浜ゆ槗璁㈠崟缂栧彿锛屽叧鑱?TradeOrderDO 鐨?id 缂栧彿',
  `order_item_id` bigint(20) NULL DEFAULT 0 COMMENT '浜ゆ槗璁㈠崟椤圭紪鍙凤紝鍏宠仈 TradeOrderItemDO 鐨?id 缂栧彿',
  `spu_id` bigint(20) NOT NULL COMMENT '鍟嗗搧 SPU 缂栧彿锛屽叧鑱?ProductSpuDO 鐨?id',
  `spu_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '鍟嗗搧 SPU 鍚嶇О',
  `sku_id` bigint(20) NOT NULL COMMENT '鍟嗗搧 SKU 缂栧彿锛屽叧鑱?ProductSkuDO 鐨?id 缂栧彿',
  `sku_pic_url` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '鍥剧墖鍦板潃',
  `sku_properties` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '灞炴?鏁扮粍锛孞SON 鏍煎紡 [{propertId: , valueId: }, {propertId: , valueId: }]',
  `visible` bit(1) NULL DEFAULT NULL COMMENT '鏄?惁鍙??锛宼rue:鏄剧ずfalse:闅愯棌',
  `scores` tinyint(4) NOT NULL COMMENT '璇勫垎鏄熺骇1-5鍒',
  `description_scores` tinyint(4) NOT NULL COMMENT '鎻忚堪鏄熺骇 1-5 鏄',
  `benefit_scores` tinyint(4) NOT NULL COMMENT '鏈嶅姟鏄熺骇 1-5 鏄',
  `content` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '璇勮?鍐呭?',
  `pic_urls` varchar(4096) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '璇勮?鍥剧墖鍦板潃鏁扮粍',
  `reply_status` bit(1) NULL DEFAULT b'0' COMMENT '鍟嗗?鏄?惁鍥炲?',
  `reply_user_id` bigint(20) NULL DEFAULT NULL COMMENT '鍥炲?绠＄悊鍛樼紪鍙凤紝鍏宠仈 AdminUserDO 鐨?id 缂栧彿',
  `reply_content` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '鍟嗗?鍥炲?鍐呭?',
  `reply_time` datetime NULL DEFAULT NULL COMMENT '鍟嗗?鍥炲?鏃堕棿',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '鍒涘缓鑰',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '鏇存柊鑰',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '鏄?惁鍒犻櫎',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '绉熸埛缂栧彿',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '鍟嗗搧璇勮?' ROW_FORMAT = DYNAMIC;

