  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '绉熸埛缂栧彿',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '鏄?惁鍒犻櫎',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_name`(`name`(32)) USING BTREE COMMENT '瑙勬牸鍚嶇О绱㈠紩'
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '鍟嗗搧灞炴?椤' ROW_FORMAT = DYNAMIC;

