CREATE TABLE `product_property_value`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '缂栧彿',
  `property_id` bigint(20) NULL DEFAULT NULL COMMENT '灞炴?椤圭殑缂栧彿',
