DROP TABLE IF EXISTS `product_sku`;
CREATE TABLE `product_sku`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '涓婚敭',
  `spu_id` bigint(20) NOT NULL COMMENT 'spu缂栧彿',
  `properties` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '灞炴?鏁扮粍锛孞SON 鏍煎紡 [{propertId: , valueId: }, {propertId: , valueId: }]',
  `price` int(11) NOT NULL DEFAULT -1 COMMENT '鍟嗗搧浠锋牸锛屽崟浣嶏細鍒',
  `market_price` int(11) NULL DEFAULT NULL COMMENT '甯傚満浠凤紝鍗曚綅锛氬垎',
  `cost_price` int(11) NOT NULL DEFAULT -1 COMMENT '鎴愭湰浠凤紝鍗曚綅锛?鍒',
  `bar_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'SKU 鐨勬潯褰㈢爜',
  `pic_url` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鍥剧墖鍦板潃',
  `stock` int(11) NULL DEFAULT NULL COMMENT '搴撳瓨',
  `weight` double NULL DEFAULT NULL COMMENT '鍟嗗搧閲嶉噺锛屽崟浣嶏細kg 鍗冨厠',
  `volume` double NULL DEFAULT NULL COMMENT '鍟嗗搧浣撶Н锛屽崟浣嶏細m^3 骞崇背',
  `first_brokerage_price` int(11) NULL DEFAULT NULL COMMENT '涓?骇鍒嗛攢鐨勪剑閲戯紝鍗曚綅锛氬垎',
  `second_brokerage_price` int(11) NULL DEFAULT NULL COMMENT '浜岀骇鍒嗛攢鐨勪剑閲戯紝鍗曚綅锛氬垎',
  `sales_count` int(11) NULL DEFAULT NULL COMMENT '鍟嗗搧閿?噺',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鍒涘缓浜',
  `updater` double(64, 0) NULL DEFAULT NULL COMMENT '鏇存柊浜',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '鏄?惁鍒犻櫎',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '绉熸埛缂栧彿',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '鍟嗗搧sku' ROW_FORMAT = DYNAMIC;

