DROP TABLE IF EXISTS `product_spu`;
CREATE TABLE `product_spu`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '鍟嗗搧 SPU 缂栧彿锛岃嚜澧',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鍟嗗搧鍚嶇О',
  `keyword` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鍏抽敭瀛',
  `introduction` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鍟嗗搧绠?粙',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '鍟嗗搧璇︽儏',
  `category_id` bigint(20) NOT NULL COMMENT '鍟嗗搧鍒嗙被缂栧彿',
  `brand_id` int(11) NULL DEFAULT NULL COMMENT '鍟嗗搧鍝佺墝缂栧彿',
  `pic_url` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鍟嗗搧灏侀潰鍥',
  `slider_pic_urls` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '鍟嗗搧杞?挱鍥惧湴鍧? 鏁扮粍锛屼互閫楀彿鍒嗛殧\n 鏈??涓婁紶15寮',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '鎺掑簭瀛楁?',
  `status` tinyint(4) NOT NULL COMMENT '鍟嗗搧鐘舵?: 1 涓婃灦锛堝紑鍚?級 0 涓嬫灦锛堢?鐢?級 -1 鍥炴敹',
  `spec_type` bit(1) NULL DEFAULT NULL COMMENT '瑙勬牸绫诲瀷锛? 鍗曡?鏍?1 澶氳?鏍',
  `price` int(11) NOT NULL DEFAULT -1 COMMENT '鍟嗗搧浠锋牸锛屽崟浣嶄娇鐢?細鍒',
  `market_price` int(11) NULL DEFAULT NULL COMMENT '甯傚満浠凤紝鍗曚綅浣跨敤锛氬垎',
  `cost_price` int(11) NOT NULL DEFAULT -1 COMMENT '鎴愭湰浠凤紝鍗曚綅锛?鍒',
  `stock` int(11) NOT NULL DEFAULT 0 COMMENT '搴撳瓨',
  `delivery_types` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '閰嶉?鏂瑰紡鏁扮粍',
  `delivery_template_id` bigint(20) NULL DEFAULT NULL COMMENT '鐗╂祦閰嶇疆妯℃澘缂栧彿',
  `give_integral` int(11) NOT NULL DEFAULT 0 COMMENT '璧犻?绉?垎',
  `sub_commission_type` bit(1) NULL DEFAULT NULL COMMENT '鍒嗛攢绫诲瀷',
  `sales_count` int(11) NULL DEFAULT 0 COMMENT '鍟嗗搧閿?噺',
  `virtual_sales_count` int(11) NULL DEFAULT 0 COMMENT '铏氭嫙閿?噺',
  `browse_count` int(11) NULL DEFAULT 0 COMMENT '鍟嗗搧鐐瑰嚮閲',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鍒涘缓浜',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鏇存柊浜',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '鏄?惁鍒犻櫎',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '绉熸埛缂栧彿',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 640 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '鍟嗗搧spu' ROW_FORMAT = DYNAMIC;

