-- ----------------------------
-- Table structure for product_statistics
-- ----------------------------
DROP TABLE IF EXISTS `product_statistics`;
CREATE TABLE `product_statistics`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '缂栧彿锛屼富閿?嚜澧',
  `time` date NOT NULL COMMENT '缁熻?鏃ユ湡',
  `spu_id` bigint(20) NOT NULL COMMENT '鍟嗗搧 SPU 缂栧彿',
  `browse_count` int(11) NOT NULL DEFAULT 0 COMMENT '娴忚?閲',
  `browse_user_count` int(11) NOT NULL DEFAULT 0 COMMENT '璁垮?閲',
  `favorite_count` int(11) NOT NULL DEFAULT 0 COMMENT '鏀惰棌鏁伴噺',
  `cart_count` int(11) NOT NULL DEFAULT 0 COMMENT '鍔犺喘鏁伴噺',
  `order_count` int(11) NOT NULL DEFAULT 0 COMMENT '涓嬪崟浠舵暟',
  `order_pay_count` int(11) NOT NULL DEFAULT 0 COMMENT '鏀?粯浠舵暟',
  `order_pay_price` int(11) NOT NULL DEFAULT 0 COMMENT '鏀?粯閲戦?锛屽崟浣嶏細鍒',
  `after_sale_count` int(11) NOT NULL DEFAULT 0 COMMENT '閫??浠舵暟',
  `after_sale_refund_price` int(11) NOT NULL DEFAULT 0 COMMENT '閫??閲戦?锛屽崟浣嶏細鍒',
  `browse_convert_percent` int(11) NOT NULL DEFAULT 0 COMMENT '璁垮?鏀?粯杞?寲鐜囷紙鐧惧垎姣旓級',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '鍒涘缓鑰',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '鏇存柊鑰',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '鏄?惁鍒犻櫎',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '绉熸埛缂栧彿',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_time`(`time`) USING BTREE,
  INDEX `idx_spu_id`(`spu_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 76 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '鍟嗗搧缁熻?琛' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of product_statistics
-- ----------------------------

-- ----------------------------
-- Table structure for property
-- ----------------------------
DROP TABLE IF EXISTS `property`;
CREATE TABLE `property`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `property_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资产编码',
  `label_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资产标签链接',
  `type` int(11) NULL DEFAULT NULL COMMENT '资产分类',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资产名称',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '资产状态',
  `brand` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '品牌',
  `model_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '型号',
  `device_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '设备序列号',
  `process_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程编号',
  `admin_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '管理员id',
  `admin_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '管理员姓名',
  `village_id` bigint(20) NULL DEFAULT NULL COMMENT '目标房源项目id',
  `build_id` bigint(20) NULL DEFAULT NULL COMMENT '目标房源楼宇id',
  `room_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '目标房源房间id',
  `build_bind` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '绑定的目标房源json',
  `position_id` bigint(20) NULL DEFAULT NULL COMMENT '所在位置配置信息id',
  `position_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资产操作时的位置信息',
  `purchase_time` timestamp NULL DEFAULT NULL COMMENT '购置时间',
  `purchase_type` tinyint(4) NULL DEFAULT NULL COMMENT '购置方式',
  `purchase_amount` decimal(19, 2) NOT NULL DEFAULT 0.00 COMMENT '购置金额(含税)',
  `stock_time` timestamp NULL DEFAULT NULL COMMENT '入库时间',
  `expect_months` bigint(20) NULL DEFAULT 0 COMMENT '预计使用期限(月)',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '备注',
  `image_hash` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '图片hash值',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资产图片url',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '使用人',
  `department_id` bigint(20) NULL DEFAULT NULL COMMENT '使用部门id',
  `receive_time` timestamp NULL DEFAULT NULL COMMENT '领用日期',
  `maintain_time` timestamp NULL DEFAULT NULL COMMENT '保养到期时间',
  `maintain_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '保养说明',
  `depreciation_months` int(11) NULL DEFAULT 0 COMMENT '预计折旧期限(月)',
  `cuser_uid` bigint(20) NULL DEFAULT 0 COMMENT '操作人uid',
  `muser_uid` bigint(20) NULL DEFAULT 0 COMMENT '修改人uid',
  `knowledge_base` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '所属资产的知识库',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_type`(`type`) USING BTREE,
  INDEX `idx_name`(`name`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_brand`(`brand`) USING BTREE,
  INDEX `idx_model`(`model_name`) USING BTREE,
  INDEX `idx_admin_id`(`admin_id`) USING BTREE,
  INDEX `idx_admin_uid`(`admin_name`) USING BTREE,
  INDEX `idx_position_id`(`position_id`) USING BTREE,
  INDEX `idx_purchase_time`(`purchase_time`) USING BTREE,
  INDEX `idx_purchase_type`(`purchase_type`) USING BTREE,
  INDEX `idx_stock_time`(`stock_time`) USING BTREE,
  INDEX `idx_image_hash`(`image_hash`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_receive_time`(`receive_time`) USING BTREE,
  INDEX `idx_maintain_time`(`maintain_time`) USING BTREE,
  INDEX `idx_cuser_uid`(`cuser_uid`) USING BTREE,
  INDEX `idx_muser_uid`(`muser_uid`) USING BTREE,
  INDEX `idx_department_id`(`department_id`) USING BTREE,
  INDEX `idx_process_code`(`process_code`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_build_id`(`build_id`) USING BTREE,
  INDEX `idx_position_name`(`position_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '资产管理表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of property
-- ----------------------------

-- ----------------------------
-- Table structure for property_approve
-- ----------------------------
DROP TABLE IF EXISTS `property_approve`;
CREATE TABLE `property_approve`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构id',
  `village_id` bigint(20) NULL DEFAULT NULL COMMENT '项目id',
  `build_id` bigint(20) NULL DEFAULT NULL COMMENT '楼宇id',
  `room_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '房间id',
  `approve_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审批单据编号',
  `relation_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联单据编号',
  `relation_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联单据类型',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '1=待审批(审批中);2=审批通过(已完结);3=审批不通过;4=已撤回(关闭申请);',
  `process_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审批业务类型',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '审批内容',
  `launch_time` timestamp NULL DEFAULT NULL COMMENT '发起时间',
  `approve_overtime` timestamp NULL DEFAULT NULL COMMENT '审批完结时间',
  `expect_revert_time` timestamp NULL DEFAULT NULL COMMENT '预计归还时间',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '原因备注',
  `department_id` bigint(20) NULL DEFAULT NULL COMMENT '申请部门id',
  `handover_uid` bigint(20) NULL DEFAULT NULL COMMENT '交接后使用人uid',
  `handover_department_id` bigint(20) NULL DEFAULT NULL COMMENT '交接后使用部门id',
  `approval_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '审批应用流程id',
  `cuser_uid` bigint(20) NOT NULL DEFAULT 0 COMMENT '提交人uid',
  `muser_uid` bigint(20) NOT NULL DEFAULT 0 COMMENT '修改人uid',
  `end_inventory_after` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '结束盘点之后的操作1已盘资产更新内容、2盘盈资产自动入库、3未盘资产自动盘亏',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_build_id`(`build_id`) USING BTREE,
  INDEX `idx_approve_number`(`approve_number`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_process_type`(`process_type`) USING BTREE,
  INDEX `idx_cuser_uid`(`cuser_uid`) USING BTREE,
  INDEX `idx_muser_uid`(`muser_uid`) USING BTREE,
  INDEX `idx_relation_number`(`relation_number`) USING BTREE,
  INDEX `idx_relation_type`(`relation_type`) USING BTREE,
  INDEX `idx_handover_uid`(`handover_uid`) USING BTREE,
  INDEX `idx_handover_department_id`(`handover_department_id`) USING BTREE,
  INDEX `idx_approval_id`(`approval_id`) USING BTREE,
  INDEX `idx_expect_revert_time`(`expect_revert_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 62 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '资产单据审批记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of property_approve
-- ----------------------------

-- ----------------------------
-- Table structure for property_category
-- ----------------------------
DROP TABLE IF EXISTS `property_category`;
CREATE TABLE `property_category`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT 0 COMMENT '机构ID',
  `number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类编码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类名称',
  `level` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '分类级别字符串，逗号拼接上级id',
  `parent_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '父级id',
  `param` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '参数',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '显示状态，2禁用 1显示，0隐藏',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
