  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_parentid`(`parent_id`) USING BTREE,
  INDEX `idx_sort`(`sort`) USING BTREE
