  `departmentIds` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '部门id',
  `positionIds` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '位置id',
  `property_status` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '支付状态',
  `admin_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '管理员id',
  `purchase_type` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '购置方式',
  `status` tinyint(4) NULL DEFAULT 0 COMMENT '完成状态 1是0否',
  `is_all` int(11) NOT NULL DEFAULT 1 COMMENT '是否是全部权限',
  `exter_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '每个用户的范围回显冗余字段',
