-- ----------------------------
-- Table structure for property_inventory_list
-- ----------------------------
DROP TABLE IF EXISTS `property_inventory_list`;
CREATE TABLE `property_inventory_list`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT 0 COMMENT '机构id',
  `number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单据编号',
  `inventory_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '盘点清单名称',
  `inventory_status` tinyint(4) NULL DEFAULT 0 COMMENT '盘点清单状态 0 盘点中 1盘点审批中 2已完结',
  `process_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程编号',
  `inventory_uid` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '盘点人',
  `restrict_field` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '资产限制字段',
  `departmentIds` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '盘点范围（使用部门）',
  `typeIds` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '盘点范围（资产分类）',
  `positionIds` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '盘点范围（资产位置）',
  `property_status` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '资产状态',
  `initiative_pay_status` int(11) NULL DEFAULT 0 COMMENT '主付状态',
  `admin_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '管理员id',
  `company` bigint(20) NULL DEFAULT 0 COMMENT '所属公司',
  `purchase_type` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '购置方式',
  `code_inventory_type` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '仅扫码盘点的分类',
  `notBreach_inventory_type` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '不可批量盘点的分类',
  `upload_type` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'ntake_pic:仅上传拍照 ntask_pic_after:在原有基础在补充',
  `is_batch` int(11) NULL DEFAULT 0 COMMENT '是否批量分配 1是0否',
  `distribution_range` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '单个分配 分配范围',
  `exter_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '额外数据、部门和分类的回显',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '资产盘点清单表' ROW_FORMAT = Dynamic;

