-- Table structure for property_inventory_record
-- ----------------------------
DROP TABLE IF EXISTS `property_inventory_record`;
CREATE TABLE `property_inventory_record`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT 0 COMMENT '机构id',
  `inventory_id` bigint(20) NULL DEFAULT NULL COMMENT '盘点清单id',
  `property_id` bigint(20) NULL DEFAULT NULL COMMENT '资产id',
  `type_id` bigint(20) NULL DEFAULT NULL COMMENT '资产分类id',
  `status` int(11) NULL DEFAULT 0 COMMENT '0未盘 1已盘 2异常 3盘盈 4盘亏 5已结束',
  `property_status` int(11) NULL DEFAULT 0 COMMENT '资产状态',
  `is_range` int(11) NULL DEFAULT 1 COMMENT '是否在盘点范围之内',
  `is_update` int(11) NOT NULL DEFAULT 0 COMMENT '是否修改资产信息 0否 1是',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '盘点备注',
  `image` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '盘点图片',
  `tag` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '盘点标签',
  `inventory_time` datetime NULL DEFAULT NULL COMMENT '盘点时间',
  `inventory_uid` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '盘点人',
  `position_id` bigint(20) NULL DEFAULT NULL COMMENT '当前位置',
  `handle_uid` bigint(20) NULL DEFAULT NULL COMMENT '处理人',
  `department_id` bigint(20) NULL DEFAULT NULL COMMENT '资产所属部门id',
  `property_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '资产盘点信息',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资产名称',
  `property_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资产编码',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_inventory_id`(`inventory_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '资产盘点记录表' ROW_FORMAT = Dynamic;

