-- ----------------------------
-- Table structure for property_lendout
-- ----------------------------
DROP TABLE IF EXISTS `property_lendout`;
CREATE TABLE `property_lendout`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT 0 COMMENT '机构id',
