  `number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单据编号',
  `type` smallint(6) NOT NULL DEFAULT 1 COMMENT '数据类型;1=借出;2=归还',
  `process_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程编号',
  `status` tinyint(4) NULL DEFAULT NULL COMMENT '单据状态',
  `lend_uid` bigint(20) NOT NULL DEFAULT 0 COMMENT '借用人uid',
  `department_id` bigint(20) NULL DEFAULT NULL COMMENT '借用部门id',
  `lend_time` timestamp NULL DEFAULT NULL COMMENT '借出时间',
  `expect_revert_time` timestamp NULL DEFAULT NULL COMMENT '预计归还时间',
  `operate_uid` bigint(20) NOT NULL DEFAULT 0 COMMENT '处理人',
  `operate_time` timestamp NULL DEFAULT NULL COMMENT '处理时间',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '借出备注',
  `cuser_uid` bigint(20) NOT NULL DEFAULT 0 COMMENT '操作人uid',
  `muser_uid` bigint(20) NOT NULL DEFAULT 0 COMMENT '修改人uid',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_build_id`(`build_id`) USING BTREE,
  INDEX `idx_room_id`(`room_id`) USING BTREE,
  INDEX `idx_number`(`number`) USING BTREE,
  INDEX `idx_process_code`(`process_code`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_department_id`(`department_id`) USING BTREE,
  INDEX `idx_lend_uid`(`lend_uid`) USING BTREE,
  INDEX `idx_lend_time`(`lend_time`) USING BTREE,
  INDEX `idx_expect_revert_time`(`expect_revert_time`) USING BTREE,
  INDEX `idx_operate_uid`(`operate_uid`) USING BTREE,
  INDEX `idx_operate_time`(`operate_time`) USING BTREE,
  INDEX `idx_cuser_uid`(`cuser_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '资产借出表' ROW_FORMAT = Dynamic;

