  INDEX `idx_org_oss_hash`(`tenant_id`, `oss_hash`) USING BTREE,
  INDEX `idx_cuser_uid`(`cuser_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '资产静态资源管理表' ROW_FORMAT = Dynamic;

