-- ----------------------------
-- Table structure for property_stuff
-- ----------------------------
DROP TABLE IF EXISTS `property_stuff`;
CREATE TABLE `property_stuff`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT 0 COMMENT '机构id',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料编码',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '物料名称',
  `category_id` bigint(20) NULL DEFAULT NULL COMMENT '物料分类id',
  `bar_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '商品条码',
  `brand` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '品牌',
  `model_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规格型号',
  `meter_unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '计量单位',
  `quantity_digit` smallint(6) NOT NULL DEFAULT 0 COMMENT '小数位数(数量)',
  `price_digit` smallint(6) NOT NULL DEFAULT 0 COMMENT '小数位数(单价)',
  `compute_method` smallint(6) NOT NULL DEFAULT 1 COMMENT '成本计算方法;1=加权平均,2=批次管理',
  `lock_price` smallint(6) NULL DEFAULT NULL COMMENT '是否固定入库单价;0=否1=是',
  `price` decimal(18, 4) NULL DEFAULT NULL COMMENT '入库单价;最多保留小数点后四位',
  `safe_stock_up` decimal(16, 2) NULL DEFAULT NULL COMMENT '安全固定上限数量',
  `safe_stock_lower` decimal(16, 2) NULL DEFAULT NULL COMMENT '安全固定下限数量',
  `receive_limit` decimal(16, 2) NULL DEFAULT NULL COMMENT '限领数量(人/月)',
  `has_return` smallint(6) NULL DEFAULT NULL COMMENT '是否允许退库;0=否;1=是',
  `image_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '物料照片;支持多张',
  `status` smallint(6) NOT NULL DEFAULT 1 COMMENT '耗材状态;1=启用;0=禁用',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '备注',
  `cuser_uid` int(11) NULL DEFAULT 0 COMMENT '操作人uid',
  `muser_uid` int(11) NULL DEFAULT 0 COMMENT '修改人uid',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_cuser_uid`(`cuser_uid`) USING BTREE,
  INDEX `idx_muser_uid`(`muser_uid`) USING BTREE,
  INDEX `idx_number`(`number`) USING BTREE,
  INDEX `idx_name`(`name`) USING BTREE,
  INDEX `idx_category_id`(`category_id`) USING BTREE,
  INDEX `idx_brand`(`brand`) USING BTREE,
  INDEX `idx_compute_method`(`compute_method`) USING BTREE,
  INDEX `idx_lock_price`(`lock_price`) USING BTREE,
  INDEX `idx_has_return`(`has_return`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '耗材档案信息表' ROW_FORMAT = Dynamic;

