  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT 0 COMMENT '机构id',
  `process_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '流程编号',
  `process_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单据编号',
  `out_admin_uid` bigint(20) NOT NULL DEFAULT 0 COMMENT '调出管理员',
  `in_admin_uid` bigint(20) NOT NULL DEFAULT 0 COMMENT '调入管理员',
  `out_depository_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '调出仓库',
  `in_depository_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '调入仓库',
  `total_num` decimal(12, 4) NULL DEFAULT NULL COMMENT '合计数量',
  `total_price` decimal(12, 4) NULL DEFAULT NULL COMMENT '合计金额',
  `status` smallint(6) NOT NULL DEFAULT 1 COMMENT '单据状态;1=进行中;2=已打回;3=已撤销;4=已完结',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '调拨备注',
  `cuser_uid` bigint(20) NULL DEFAULT 0 COMMENT '处理人uid',
  `muser_uid` bigint(20) NULL DEFAULT 0 COMMENT '修改人uid',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_out_admin_uid`(`out_admin_uid`) USING BTREE,
  INDEX `idx_in_admin_uid`(`in_admin_uid`) USING BTREE,
  INDEX `idx_cuser_uid`(`cuser_uid`) USING BTREE,
  INDEX `idx_muser_uid`(`muser_uid`) USING BTREE,
  INDEX `idx_process_code`(`process_code`) USING BTREE,
  INDEX `idx_process_number`(`process_number`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '耗材业务调拨表' ROW_FORMAT = Dynamic;

