  INDEX `idx_muser_uid`(`muser_uid`) USING BTREE,
  INDEX `idx_field_limit`(`field_limit`) USING BTREE,
  INDEX `idx_has_logo`(`has_logo`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '资产标签模板表' ROW_FORMAT = Dynamic;

