  `booking_id` int(11) NULL DEFAULT NULL COMMENT '预约ID',
  `order_id` int(11) NOT NULL COMMENT '预约订单ID',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '退款订单号',
  `amount` decimal(11, 2) NOT NULL COMMENT '退款金额',
  `actual_amount` decimal(11, 2) NULL DEFAULT NULL COMMENT '实际退款金额',
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `owner_id` int(11) NOT NULL DEFAULT 0 COMMENT '租客ID',
  `handler` int(11) NULL DEFAULT NULL COMMENT '处理人',
  `handler_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '处理人名称',
  `handle_time` timestamp NULL DEFAULT NULL COMMENT '处理时间',
  `refund_type` tinyint(4) NULL DEFAULT NULL COMMENT '退款类型 1 全部退款 2 部分退款',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0未处理 1已处理 2驳回',
  `error_msg` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '退款错误日志',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `reav_booking_order_refund_order_no_app_sign_index`(`order_no`, `app_sign`) USING BTREE,
  INDEX `reav_booking_order_refund_booking_id_index`(`booking_id`) USING BTREE,
  INDEX `reav_booking_order_refund_order_id_index`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '预约订单退款表' ROW_FORMAT = Dynamic;

