  UNIQUE INDEX `resv_application_sign_unique`(`sign`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '预约应用' ROW_FORMAT = Dynamic;

