-- ----------------------------
-- Table structure for village
-- ----------------------------
DROP TABLE IF EXISTS `village`;
CREATE TABLE `village`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目名称',
  `short_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目名称缩写',
  `describe` varchar(5000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目介绍',
  `logo` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目LOGO',
  `district_txt` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目省市区地址',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目详细地址',
  `lng` decimal(10, 6) NULL DEFAULT NULL COMMENT '落座经度（gcj02）',
  `lat` decimal(10, 6) NULL DEFAULT NULL COMMENT '落座纬度（gcj02）',
  `management_area` decimal(16, 2) NULL DEFAULT 0.00 COMMENT '管理面积',
  `rentable_area` decimal(16, 2) NULL DEFAULT 0.00 COMMENT '可招商面积',
  `room_rentable_count` int(11) NULL DEFAULT 0 COMMENT '可招商房源数量',
  `room_count` int(11) NULL DEFAULT 0 COMMENT '总房源数量',
  `tag_id_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '标签（数组存储）',
  `wechat_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目公众号的微信号',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '数据状态',
  `three_dimensional_file` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '3D模型',
  `three_dimensional_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '3D模型物体ID',
  `dimensional_bg_img` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '楼宇图片',
  `room_status_color` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '房源到期的颜色值数组',
  `org_id` int(11) NOT NULL DEFAULT 0 COMMENT '当前管理的机构ID',
  `country_id` int(11) NOT NULL DEFAULT 0 COMMENT '国家ID',
  `province_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '省份ID',
  `city_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '城市ID',
  `district_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '区县ID',
  `street_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '街道/乡镇ID',
  `community_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '社区/村ID',
  `room_min_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '房间最低单价（月）',
  `room_average_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '房间平均单价（月）',
  `traffic_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '附近公共交通相关信息',
  `type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业态',
  `extra_config` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '额外扩展配置',
  `vr_link` varchar(5000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'vr链接',
  `video` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '视频地址',
  `vr_video_sort` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'VR视频导致的排序（VR和视频30，VR20，视频10，没有0）',
  `month_hits` int(11) NOT NULL DEFAULT 0 COMMENT '月浏览数（计划任务统计）',
  `sort` int(11) NULL DEFAULT NULL COMMENT '排序值',
  `micro_service_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '围绕项目服务的子项目配置信息，例如人脸识别设备',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_org_id`(`org_id`) USING BTREE,
  INDEX `idx_type`(`type`) USING BTREE,
  INDEX `idx_sort`(`sort`) USING BTREE,
  INDEX `idx_country_id`(`country_id`) USING BTREE,
  INDEX `idx_province_id`(`province_id`) USING BTREE,
  INDEX `idx_city_id`(`city_id`) USING BTREE,
  INDEX `idx_district_id`(`district_id`) USING BTREE,
  INDEX `idx_street_id`(`street_id`) USING BTREE,
  INDEX `idx_community_id`(`community_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '社区表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of village
-- ----------------------------

-- ----------------------------
-- Table structure for village_build
-- ----------------------------
DROP TABLE IF EXISTS `village_build`;
CREATE TABLE `village_build`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `build_number` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '楼栋编号',
  `build_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '楼栋名称',
  `logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '楼宇lOGO',
  `zone_id` int(11) NULL DEFAULT NULL COMMENT '分区ID',
  `village_id` int(11) NULL DEFAULT NULL COMMENT '项目ID',
  `have_unit` tinyint(4) NOT NULL DEFAULT 0 COMMENT '有没有单元，1有，0没有',
  `district_txt` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目省市区地址',
  `country_id` int(11) NOT NULL DEFAULT 0 COMMENT '国家ID',
  `province_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '省份ID',
  `city_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '城市ID',
  `district_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '区县ID',
  `street_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '街道/乡镇ID',
  `community_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '社区/村ID',
  `lng` decimal(10, 6) NULL DEFAULT NULL COMMENT '落座经度（gcj02）',
  `lat` decimal(10, 6) NULL DEFAULT NULL COMMENT '落座纬度（gcj02）',
  `address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '地址',
  `floor_height` decimal(11, 2) NULL DEFAULT NULL COMMENT '标准层高',
  `property_right` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '产权性质',
  `build_area` decimal(11, 2) NULL DEFAULT NULL COMMENT '建筑面积',
  `property_area` decimal(11, 2) NULL DEFAULT NULL COMMENT '产权面积',
  `rentable_area` decimal(11, 2) NULL DEFAULT NULL COMMENT '可租面积',
  `self_use_area` decimal(11, 2) NULL DEFAULT NULL COMMENT '自用面积',
  `supporting_area` decimal(11, 2) NULL DEFAULT NULL COMMENT '配套面积',
  `property_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '产权编号',
  `land_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '土地编号',
  `estate_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '不动产证编号',
  `parking_area` decimal(11, 2) NULL DEFAULT NULL COMMENT '车位面积',
  `parking_count` int(11) NULL DEFAULT NULL COMMENT '车位数量',
  `management_area` decimal(11, 2) NULL DEFAULT NULL COMMENT '管理面积',
  `room_count` int(11) NOT NULL DEFAULT 0 COMMENT '房间总数',
  `rent_in_area` decimal(11, 2) NULL DEFAULT 0.00 COMMENT '在租面积',
  `rent_in_room` int(11) NOT NULL DEFAULT 0 COMMENT '在租房间数',
  `rent_in_contract` int(11) NOT NULL DEFAULT 0 COMMENT '在租合同数',
  `invitation_room_count` int(11) NOT NULL DEFAULT 0 COMMENT '招商房间总数',
  `revenue_target` json NULL COMMENT '营收目标(数组存储)',
  `account_default` int(11) NULL DEFAULT NULL COMMENT '默认收支账户',
  `extra_config` json NULL COMMENT '默认配置',
  `tag_info` json NULL COMMENT '楼宇标签',
  `is_hot` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否热门',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '排序，越大越前',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '数据状态(1使用，0隐藏)',
  `three_dimensional_file` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '3D模型',
  `three_dimensional_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '3D模型物体ID',
  `dimensional_bg_img` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '实景图',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  `org_id` int(11) NULL DEFAULT 0 COMMENT '当前管理的机构ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_zone_id`(`zone_id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目楼栋表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of village_build
-- ----------------------------

-- ----------------------------
-- Table structure for village_control_menu
-- ----------------------------
DROP TABLE IF EXISTS `village_control_menu`;
CREATE TABLE `village_control_menu`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单名称',
  `icon` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '菜单图标（http开头视为图片）',
  `active_icon` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '菜单选中图标（http开头视为图片）',
  `menu_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'room' COMMENT '按钮集合类型，暂定 village、build、room、villageUser',
  `alias` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '路由别名，http开头即认定为iframe',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '菜单排序，越高越前',
  `micro` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微服务提供',
  `app` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '前端服务',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_name`(`name`) USING BTREE,
  INDEX `idx_menu_type`(`menu_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目租控管理菜单' ROW_FORMAT = Dynamic;

