  INDEX `idx_room_id`(`room_id`) USING BTREE,
  INDEX `idx_layer_id`(`layer_id`) USING BTREE,
  INDEX `idx_unit_id`(`unit_id`) USING BTREE,
  INDEX `idx_build_id`(`build_id`) USING BTREE,
  INDEX `idx_zone_id`(`zone_id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目IC卡表（可能会绑定人员，因不同设备需要而定）' ROW_FORMAT = Dynamic;

