  INDEX `idx_zone_id`(`zone_id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 80 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目楼层表' ROW_FORMAT = Dynamic;

