-- ----------------------------
-- Table structure for village_room
-- ----------------------------
DROP TABLE IF EXISTS `village_room`;
CREATE TABLE `village_room`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `room_number` int(11) NULL DEFAULT NULL COMMENT '房间编号',
  `room_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '房间名称',
  `room_alias_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '房间管理编号',
  `parent_room_id` int(11) NULL DEFAULT NULL COMMENT '父级房间编号',
  `sub_room_count` smallint(6) NULL DEFAULT 0 COMMENT '子房间总数',
  `sub_room_rent_count` smallint(6) NULL DEFAULT 0 COMMENT '子房间已租总数',
  `build_area` decimal(12, 2) NULL DEFAULT NULL COMMENT '建筑面积',
  `inside_area` decimal(12, 2) NULL DEFAULT NULL COMMENT '套内面积（实际使用面积）',
  `rental_area` decimal(12, 2) NULL DEFAULT NULL COMMENT '计租面积',
  `rental_area_in` decimal(12, 2) NULL DEFAULT NULL COMMENT '计租面积（在租）',
  `charging_area` decimal(12, 2) NULL DEFAULT NULL COMMENT '计费面积',
  `charging_area_in` decimal(12, 2) NULL DEFAULT NULL COMMENT '计费面积（在租）',
  `lease_start` datetime NULL DEFAULT NULL COMMENT '租赁开始时间',
  `lease_end` datetime NULL DEFAULT NULL COMMENT '租赁结束时间',
  `deliver_time` datetime NULL DEFAULT NULL COMMENT '交付时间',
  `invitation_status` tinyint(4) NULL DEFAULT NULL COMMENT '1招商，0不招商（出租后默认设置不招商）',
  `investment_policy` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '招商政策',
  `investment_conditions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '招商条件',
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '图集数组',
  `price_unit` enum('square_month','square_day','month','day','year') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '价格单位',
  `price_unit_min` enum('square_month','square_day','month','day','year') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '底价单位',
  `pre_unit_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '预租单价',
  `pre_unit_price_min` decimal(10, 2) NULL DEFAULT NULL COMMENT '最低价格',
  `tag_id_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '房源标签ID数组',
  `contract_info` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '合同情况，记录时间、执行情况，用于判断是否逾期',
  `contract_count` int(11) NULL DEFAULT 0 COMMENT '在租合同数',
  `decoration` enum('exquisite','simple','none','standard','luxury') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '装修情况',
  `property_right` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '产权性质',
  `floor_height` decimal(10, 4) NULL DEFAULT NULL COMMENT '标准层高',
  `load_max` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '荷载值',
  `layer_id` int(11) NULL DEFAULT NULL COMMENT '楼层ID',
  `unit_id` int(11) NULL DEFAULT NULL COMMENT '单元ID',
  `build_id` int(11) NULL DEFAULT NULL COMMENT '楼栋ID',
  `zone_id` int(11) NULL DEFAULT NULL COMMENT '分区ID',
  `village_id` int(11) NULL DEFAULT NULL COMMENT '项目ID',
  `sort` int(11) NULL DEFAULT 0 COMMENT '排序，越大越前',
  `status` tinyint(4) NULL DEFAULT 1 COMMENT '数据状态(1使用，0隐藏)',
  `three_dimensional_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '3D模型物体ID',
  `room_status` tinyint(4) NULL DEFAULT 10 COMMENT '状态(<10空置状态，<20已预订，<30出租中)',
  `house_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '房源类型',
  `record_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '房源备案号',
  `promoter_money` decimal(10, 2) NULL DEFAULT NULL COMMENT '推广佣金',
  `promoter_money_unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '推广佣金单位',
  `extra_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '额外扩展配置',
  `vr_link` varchar(5000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'vr链接',
  `video` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '视频地址',
  `vr_video_sort` tinyint(4) NULL DEFAULT 0 COMMENT 'VR视频导致的排序（VR和视频30，VR20，视频10，没有0）',
  `month_hits` int(11) NULL DEFAULT 0 COMMENT '月浏览数（计划任务统计）',
  `split_parent_area` tinyint(4) NULL DEFAULT 0 COMMENT '是否占用了父房间的面积',
  `is_lock` tinyint(4) NULL DEFAULT 0 COMMENT '是否锁定房源(1锁定，0正常(取消锁定))',
  `is_unreal` smallint(6) NULL DEFAULT 0 COMMENT '0=真实房间;1=非真实房间',
  `extra_lock` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '锁定房源面积信息',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_layer_id`(`layer_id`) USING BTREE,
  INDEX `idx_unit_id`(`unit_id`) USING BTREE,
  INDEX `idx_build_id`(`build_id`) USING BTREE,
  INDEX `idx_zone_id`(`zone_id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_contract_count`(`contract_count`) USING BTREE,
  INDEX `idx_room_status`(`room_status`) USING BTREE,
  INDEX `idx_creator`(`creator`) USING BTREE,
  INDEX `idx_is_lock`(`is_lock`) USING BTREE,
  INDEX `idx_parent_room_id`(`parent_room_id`) USING BTREE,
  INDEX `idx_room_alias_id`(`room_alias_id`) USING BTREE,
  INDEX `idx_is_unreal`(`is_unreal`) USING BTREE,
  INDEX `idx_deliver_time`(`deliver_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 156 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目房间表' ROW_FORMAT = Dynamic;

