-- ----------------------------
-- Table structure for village_user
-- ----------------------------
DROP TABLE IF EXISTS `village_user`;
CREATE TABLE `village_user`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `uniqid_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '人员针对房间的唯一编号',
  `user_id` int(11) NULL DEFAULT NULL COMMENT '用户表ID，可能为空',
  `owner_id` int(11) NULL DEFAULT NULL COMMENT '归属租客ID',
  `build_id` int(11) NULL DEFAULT NULL COMMENT '楼栋ID',
  `org_id` int(11) NULL DEFAULT NULL COMMENT '部门ID',
  `village_id` int(11) NULL DEFAULT NULL COMMENT '项目ID',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '人员名称（128位加密）',
  `phone` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '人员手机号（128位加密）',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '住户联系邮箱',
  `address` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通讯地址',
  `is_default` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否为默认租客住户联系人',
  `type` smallint(6) NULL DEFAULT NULL COMMENT '0+房主，10+家属，20+租户，30+物业人员，40+服务人员，50+访客',
  `effective_time_start` timestamp NULL DEFAULT NULL COMMENT '有效期开始（特别指访客）',
  `effective_time_end` timestamp NULL DEFAULT NULL COMMENT '有效期结束（特别指访客）',
  `idcard_type` enum('idcard','gangaotai','passport') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'idcard' COMMENT '证件类型（大陆身份证、港澳台、护照等）',
  `idcard` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证件号（128位加密）',
  `birth_year` smallint(6) NULL DEFAULT NULL COMMENT '出生年（年月日尽量从身份证中获取）',
  `birth_month` smallint(6) NULL DEFAULT NULL COMMENT '出生月（年月日尽量从身份证中获取）',
  `birth_day` smallint(6) NULL DEFAULT NULL COMMENT '出生日（年月日尽量从身份证中获取）',
  `sex` tinyint(4) NOT NULL DEFAULT 0 COMMENT '性别（1男，2女，0未知）（年月日尽量从身份证中获取）',
  `edu_type` tinyint(4) NULL DEFAULT NULL COMMENT '学历信息',
  `work_year` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作年限',
  `grad_school` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '毕业院校',
  `sk_cert` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '技能证书',
  `idcard_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '身份证照片(包含手持身份证图片){\"front_url\":\"\",\"back_url\":\"\",\"hand_url\":\"\"}',
  `photo` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '照片网址（128加密）,后期若有多个用英文逗号分割',
  `photo_status` tinyint(4) NULL DEFAULT 10 COMMENT '照片数据状态（0+正常，10+审核中，20+失败）',
  `photo_status_desc` tinyint(4) NULL DEFAULT NULL COMMENT '照片状态的描述文本（一般用于状态失败原因描述）',
  `in_advance` smallint(6) NULL DEFAULT 0 COMMENT '是否拥有代付权限',
  `in_advance_notice` smallint(6) NULL DEFAULT 0 COMMENT '是否代付通知',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '数据状态（0审核中，1正常，4拒绝）',
  `last_choose_time` datetime NULL DEFAULT NULL COMMENT '租客端最后选择此身份的时间',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_uniqid_village_id`(`uniqid_id`, `village_id`) USING BTREE,
  INDEX `idx_village_id`(`village_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_owner_id`(`owner_id`) USING BTREE,
  INDEX `idx_build_id`(`build_id`) USING BTREE,
  INDEX `idx_is_default`(`is_default`) USING BTREE,
  INDEX `idx_in_advance`(`in_advance`) USING BTREE,
  INDEX `idx_advance_notice`(`in_advance_notice`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目用户/租客表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of village_user
-- ----------------------------

