  `home_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '家庭住址',
  `home_tel` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '家庭电话',
  `house_registration` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '户籍',
  `country_registration` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '国籍',
  `place_residence` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '户口所在地',
  `emerge_contact` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '紧急联系人',
  `employer` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '工作单位',
  `working_years` tinyint(4) NULL DEFAULT 0 COMMENT '工作年限',
  `company_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '单位性质',
  `work_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '工作单位地址',
  `house_type` tinyint(4) NULL DEFAULT 0 COMMENT '住房性质',
  `join_party_time` date NULL DEFAULT NULL COMMENT '入党时间',
  `month_income` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '月收入(元)',
  `retiree` tinyint(4) NULL DEFAULT 0 COMMENT '离退休人员',
  `nature_employment` tinyint(4) NULL DEFAULT 0 COMMENT '用工性质',
  `community_group` tinyint(4) NULL DEFAULT 0 COMMENT '社区重点人群',
  `foucus_children` tinyint(4) NULL DEFAULT 0 COMMENT '是否重点儿童',
  `is_dibaohu` tinyint(4) NULL DEFAULT 0 COMMENT '是否低保户',
  `insurance_type` tinyint(4) NULL DEFAULT 0 COMMENT '参保类型',
  `religious_belief` tinyint(4) NULL DEFAULT 0 COMMENT '信仰宗教',
  `skill_certificate` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '技能证书',
  `graduated_shcool` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '毕业院校',
  `unique_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '房间唯一编号id',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `village_user_extends_unique_id_unique`(`unique_id`) USING BTREE,
  INDEX `idx_index_02`(`village_id`, `user_id`, `village_user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户信息扩展' ROW_FORMAT = Dynamic;

