  INDEX `idx_is_enable`(`is_enable`) USING BTREE,
  INDEX `idx_sort`(`sort`) USING BTREE,
  INDEX `idx_sys_field_id`(`sys_field_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6481 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户扩展信息自定义系统设置' ROW_FORMAT = Dynamic;

