-- ----------------------------
-- Table structure for workorder_payment_order
-- ----------------------------
DROP TABLE IF EXISTS `workorder_payment_order`;
CREATE TABLE `workorder_payment_order`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构id',
  `application` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '应用标识',
  `bill_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '账单id',
  `bill_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '账单号',
  `approve_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单据编号',
  `owner_id` bigint(20) NULL DEFAULT NULL COMMENT '收款方、租客id',
  `total_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '金额',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '付款时间',
  `order_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工单id',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '0待审核  1同意（已生成）  2拒绝  3 撤销  4已付款',
  `cost_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '费用类型',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '付款单记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of workorder_payment_order
-- ----------------------------

-- ----------------------------
-- Table structure for workorder_payorder_approval
-- ----------------------------
DROP TABLE IF EXISTS `workorder_payorder_approval`;
CREATE TABLE `workorder_payorder_approval`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT 0 COMMENT '机构id',
  `application` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '应用标识',
  `approve_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '单据编号',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '1=待审批(审批中);2=审批通过(已完结);3=审批不通过;4=已撤回(关闭申请);',
  `process_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批业务类型',
  `content` json NULL COMMENT '审批内容',
  `approval_id` bigint(20) NULL DEFAULT 0 COMMENT '审批应用流程id',
  `approve_overtime` datetime NULL DEFAULT NULL COMMENT '审批结束时间',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '工单付款单审批记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of workorder_payorder_approval
-- ----------------------------

-- ----------------------------
-- Table structure for workorder_propose
-- ----------------------------
DROP TABLE IF EXISTS `workorder_propose`;
CREATE TABLE `workorder_propose`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `application` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应用标识',
  `repair_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '报修类型;1=室内报修;2=公共区域报修;',
  `order_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '工单类型;1=普通工单;2=付费工单;',
  `paid_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '收费方式;1=免费服务;2=下单即收费;3=完成后收费;',
  `paid_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '工单订单状态;2=已支付;3=已退款;',
  `paid_payer` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '费用支付方;1=租客承担;2=机构承担;',
  `number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工单编号',
  `category_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '工单大类id',
  `subcat_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '工单子类id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上报人名称',
  `phone` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上报人手机',
  `appear_time` datetime NULL DEFAULT NULL COMMENT '上报时间',
  `visit_time` datetime NULL DEFAULT NULL COMMENT '上门时间',
  `reserve_start_time` datetime NULL DEFAULT NULL COMMENT '预约起始时间',
  `reserve_end_time` datetime NULL DEFAULT NULL COMMENT '预约结束时间',
  `wait_time` datetime NULL DEFAULT NULL COMMENT '等待起始时间',
  `position` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '指定位置信息',
  `label_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '描述标签json',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '补充内容',
  `images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '上报图片json;支持多张',
  `village_id` bigint(20) NULL DEFAULT NULL COMMENT '项目id',
  `build_id` bigint(20) NULL DEFAULT NULL COMMENT '楼宇id',
  `room_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '房间id集合【选择室内时使用】',
  `owner_id` bigint(20) NULL DEFAULT NULL COMMENT '租客id',
  `post_uids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '当前工单所属岗位处理人json',
  `from` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工单来源',
  `source` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作来源',
  `work_app` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工单来源应用标识',
  `task_id` bigint(20) NULL DEFAULT NULL COMMENT '巡检任务id',
  `record_id` bigint(20) NULL DEFAULT NULL COMMENT '第三方发起工单的id（例如巡检整改记录id、资产维修单id）',
  `record_id2` bigint(20) NULL DEFAULT NULL COMMENT '第三方发起工单的第二个id（例如资产维修单的资产id）',
  `is_timeout` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否超时;0=否;1=是;',
  `is_change` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否可抢单;0=否;1=是;',
  `is_assign` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '可抢单是否转未指派;0=否;1=是;',
  `timeout_time` datetime NULL DEFAULT NULL COMMENT '超时起始时间',
  `change_time` datetime NULL DEFAULT NULL COMMENT '可抢单起始时间',
  `rob_time` datetime NULL DEFAULT NULL COMMENT '可抢单结束时间',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '工单状态;1=未指派,2=已指派,3=处理中,4=已办结',
  `appraise_level` int(11) NULL DEFAULT NULL COMMENT '评价等级;1-5星',
  `has_notice` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否通知',
  `has_refund` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '是否支持退款;0=否;1=是;',
  `has_open` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '是否能重新打开;0=否;1=是;',
  `followup_uid` bigint(20) NULL DEFAULT 0 COMMENT '跟进人uid',
  `rob_uid` bigint(20) NULL DEFAULT 0 COMMENT '抢单人uid',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '机构工单数据表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of workorder_propose
-- ----------------------------

-- ----------------------------
-- Table structure for workorder_propose_log
-- ----------------------------
DROP TABLE IF EXISTS `workorder_propose_log`;
CREATE TABLE `workorder_propose_log`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `workorder_id` bigint(20) NULL DEFAULT NULL COMMENT '工单id',
  `village_id` bigint(20) NULL DEFAULT NULL COMMENT '项目id',
  `build_id` bigint(20) NULL DEFAULT NULL COMMENT '楼宇id',
  `application` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应用标识',
  `from` varchar(55) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源标识',
  `source` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '业务来源;1=租客端;2=员工端;',
  `operate_type` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '操作类型',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '操作状态',
  `operate_time` datetime NULL DEFAULT NULL COMMENT '操作时间',
  `uid` bigint(20) NULL DEFAULT NULL COMMENT '处理人uid',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '处理人名称',
  `phone` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '手机号码',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '备注内容',
  `images` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '图例;支持多张',
  `other_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '备用内容json',
  `stuff_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '资产单据信息json',
  `appraise_level` int(11) NULL DEFAULT NULL COMMENT '评价等级;1-5星',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '工单操作日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of workorder_propose_log
-- ----------------------------

-- ----------------------------
-- Table structure for workorder_propose_order
-- ----------------------------
DROP TABLE IF EXISTS `workorder_propose_order`;
CREATE TABLE `workorder_propose_order`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `workorder_id` bigint(20) NULL DEFAULT 0 COMMENT '工单id',
  `village_id` bigint(20) NULL DEFAULT 0 COMMENT '项目id',
  `build_id` bigint(20) NULL DEFAULT 0 COMMENT '楼宇id',
  `room_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '房号',
  `application` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应用标识',
  `from` varchar(55) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源标识',
  `owner_id` bigint(20) NULL DEFAULT NULL COMMENT '租客id',
  `order_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '订单名称',
  `order_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '订单编号',
  `order_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '订单状态;1=待支付;2=已支付;3=已退款;4=已取消;',
  `refund_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '退款状态;1=部分;2=全额;',
  `category_id` bigint(20) NULL DEFAULT 0 COMMENT '工单大类id',
  `subcat_id` bigint(20) NULL DEFAULT 0 COMMENT '工单子类id',
  `amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '订单金额(应付金额)',
  `need_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '订单需付金额',
  `payment_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '支付金额',
  `payment_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `refund_amount` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '退款金额',
  `refund_time` datetime NULL DEFAULT NULL COMMENT '退款时间',
  `order_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '订单类型',
  `pay_method` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '支付方式',
  `third_order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '第三方订单号',
  `third_extra` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '第三方信息',
  `extra_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'extra信息',
  `stuff_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '资产单据信息json',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '1' COMMENT '订单流程状态;1=正常;0=关闭',
  `generate_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '是否生成 1未生产 2已生成',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '付费工单订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of workorder_propose_order
-- ----------------------------

-- ----------------------------
-- Table structure for workorder_rule
-- ----------------------------
DROP TABLE IF EXISTS `workorder_rule`;
CREATE TABLE `workorder_rule`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '编号',
  `org_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `application` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '应用标识',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规则名称',
  `snatch_limit` int(11) NOT NULL DEFAULT 0 COMMENT '抢单数上限;/个',
  `prepose_time` int(11) NOT NULL DEFAULT 0 COMMENT '抢单前置时长;/分钟',
  `rob_time` int(11) NOT NULL DEFAULT 0 COMMENT '抢单限制时长;单位/分钟',
  `refund_time` int(11) NOT NULL DEFAULT 0 COMMENT '可退款时长;/分钟',
  `cancel_time` int(11) NOT NULL DEFAULT 0 COMMENT '取消订单时长;/分钟',
  `restart_time` int(11) NOT NULL DEFAULT 0 COMMENT '重新打开时长;/分钟',
  `build_bind` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '绑定的楼宇信息json',
  `is_default` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0' COMMENT '是否为默认配置',
  `creator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  `is_delete` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '是否可以删除0=否1=是',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 115 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '工单规则设置表' ROW_FORMAT = Dynamic;

